/*

 * 计算分配请求大小的区域索引，并将分配请求大小设置为该区域的块大小。

 */

rt_inline intzoneindex(rt_size_t *bytes)

{

    /* 无符号整数用于位移操作 */

    rt_ubase_t n = (rt_ubase_t)(*bytes);


    if (n < 128)

    {

        /* 对齐到8字节，并计算区域索引 */

        *bytes = n = (n + 7) & ~7;

        return (n / 8 - 1);

    }

    if (n < 256)

    {

        /* 对齐到16字节，并计算区域索引 */

        *bytes = n = (n + 15) & ~15;

        return (n / 16 + 7);

    }

    /* 对于更大的内存请求，使用更大的对齐单位，并计算相应的区域索引 */

    if (n < 8192)

    {

        /* ...省略部分代码... */

    }

    if (n < 16384)

    {

        /* 对齐到1024字节，并计算区域索引 */

        *bytes = n = (n + 1023) & ~1023;

        return (n / 1024 + 55);

    }


    /* 如果内存请求大小超出预期，打印错误信息 */

    rt_kprintf("Unexpected byte count %d", n);


    return0;

}

