### i2c_waitack

- 等待ACK;在SCL高电平时,读取SDA电平,ACK为低电平,NACK为高电平

```c

rt_inline rt_bool_ti2c_waitack(struct rt_i2c_bit_ops *ops)

{

    rt_bool_t ack;


    SDA_H(ops);

    i2c_delay(ops);


    if (SCL_H(ops) < 0)

    {

        LOG_W("wait ack timeout");


        return -RT_ETIMEOUT;

    }


    ack = !GET_SDA(ops);    /* ACK : SDA pin is pulled low */

    LOG_D("%s", ack ? "ACK" : "NACK");


    SCL_L(ops);


    return ack;

}

```

### i2c_readb

- 从高位到低位接收数据,接收一个字节数据
- 必须在SCL高电平期间读取SDA电平

```c

staticrt_int32_ti2c_readb(struct rt_i2c_bus_device *bus)

{

    rt_uint8_t i;

    rt_uint8_t data = 0;

    struct rt_i2c_bit_ops *ops = (struct rt_i2c_bit_ops *)bus->priv;


    SDA_H(ops);

    i2c_delay(ops);

    for (i = 0; i < 8; i++)

    {

        data <<= 1;


        if (SCL_H(ops) < 0)

        {

            LOG_D("i2c_readb: wait scl pin high "

                    "timeout at bit %d", 7 - i);


            return -RT_ETIMEOUT;

        }


        if (GET_SDA(ops))

            data |= 1;

        SCL_L(ops);

        i2c_delay2(ops);

    }


    return data;

}

```

