```c

staticrt_err_ti2c_send_ack_or_nack(struct rt_i2c_bus_device *bus, intack)

{

    struct rt_i2c_bit_ops *ops = (struct rt_i2c_bit_ops *)bus->priv;


    if (ack)

        SET_SDA(ops, 0);

    i2c_delay(ops);

    if (SCL_H(ops) < 0)

