5. 计算tick补偿

```c

/* Tickless*/

if (pm->timer_mask & (0x01 << pm->sleep_mode))

{

    timeout_tick = pm_timer_next_timeout_tick(pm->sleep_mode);

    timeout_tick = timeout_tick - rt_tick_get();


    // 根据需要唤醒时间,计算下一个睡眠模式

    pm->sleep_mode = pm_get_sleep_threshold_mode(pm->sleep_mode, timeout_tick);


    if (pm->timer_mask & (0x01 << pm->sleep_mode))

    {

