                {

                    spi_delay2(ops);


                    TOG_SCLK(ops);


                    if (config->mode & RT_SPI_MSB) { rx_data <<= 1; bit = 0x01; }

                    else                           { rx_data >>= 1; bit = 0x80; }


                    if (GET_MOSI(ops)) { rx_data |=  bit; }

                    else               { rx_data &= ~bit; }


                    spi_delay2(ops);


                    if (!(config->mode & RT_SPI_CPHA) || (size != 0) || (i < 7))

                    {

                        TOG_SCLK(ops);

                    }

                }


            }


            if (recv_buf != RT_NULL)

            {

                *recv_ptr++ = rx_data;

            }

        }


        if (!send_flg)

        {

            MOSI_OUT(ops);

        }

```

