### _sdcard_mount

```c

staticvoid_sdcard_mount(void)

{

    rt_device_t device;


    device = rt_device_find("sd");


    if (device == NULL)

    {

        sdcard_change();    //发送要求mmcsd检测线程执行检测程序

        mmcsd_wait_cd_changed(RT_WAITING_FOREVER);//阻塞等待检测结果

        device = rt_device_find("sd");

    }

    if (device != RT_NULL)

