        logic_nbr[0] = '0' + index;

    }


    //临时挂载的驱动需要卸掉

    /* check flag status, we need clear the temp driver stored in disk[] */

    if (flag == FSM_STATUS_USE_TEMP_DRIVER)

    {

        rt_free(fat);

        f_mount(RT_NULL, logic_nbr, (BYTE)index);

        disk[index] = RT_NULL;

        /* close device */

        rt_device_close(dev_id);

    }

}

