## boot_ramdisk_high
```c
int boot_ramdisk_high(ulong rd_data, ulong rd_len, ulong *initrd_start,
		      ulong *initrd_end)
{
	char	*s;
	phys_addr_t initrd_high;
	int	initrd_copy_to_ram = 1;

	s = env_get("initrd_high");
	if (s) {	//从环境变量中获取initrd_high的地址
		/* a value of "no" or a similar string will act like 0,
		 * turning the "load high" feature off. This is intentional.
		 */
		initrd_high = hextoul(s, NULL);
		if (initrd_high == ~0)	//-1(未定义或无效值),则不拷贝到高地址
			initrd_copy_to_ram = 0;
	} else {
		//计算initrd_high的地址 = 内核内存映射大小 + RAM的基础地址
		initrd_high = env_get_bootm_mapsize() + env_get_bootm_low();
	}

	if (rd_data) {
		//0拷贝到高地址
		if (!initrd_copy_to_ram) {	/* zero-copy ramdisk support */
			debug("   in-place initrd\n");
			*initrd_start = rd_data;
			*initrd_end = rd_data + rd_len;
			lmb_reserve(rd_data, rd_len, LMB_NONE);
		} else {
			//拷贝到高地址
			if (initrd_high)
				*initrd_start =
					//分配一个高于initrd_high的地址,按0x1000对齐
					(ulong)lmb_alloc_base(rd_len,
								    0x1000,
								    initrd_high,
								    LMB_NONE);
			else
				//在当前地址分配内存
				*initrd_start = (ulong)lmb_alloc(rd_len,
								 0x1000);

			if (*initrd_start == 0) {
				puts("ramdisk - allocation error\n");
				goto error;
			}
			bootstage_mark(BOOTSTAGE_ID_COPY_RAMDISK);

			*initrd_end = *initrd_start + rd_len;
			printf("   Loading Ramdisk to %08lx, end %08lx ... ",
			       *initrd_start, *initrd_end);

			memmove_wd((void *)*initrd_start,
				   (void *)rd_data, rd_len, CHUNKSZ);

			/*
			 * Ensure the image is flushed to memory to handle
			 * AMP boot scenarios in which we might not be
			 * HW cache coherent
			 */
			if (IS_ENABLED(CONFIG_MP)) {
				flush_cache((unsigned long)*initrd_start,
					    ALIGN(rd_len, ARCH_DMA_MINALIGN));
			}
			puts("OK\n");
		}
	} else {
		*initrd_start = 0;
		*initrd_end = 0;
	}
	debug("   ramdisk load start = 0x%08lx, ramdisk load end = 0x%08lx\n",
	      *initrd_start, *initrd_end);

	return 0;

error:
	return -1;
}
```

