 * 返回值:成功解析到分隔符的位置返回1,否则返回0
 */
 int fit_parse_conf(const char *spec, ulong addr_curr,
		ulong *addr, const char **conf_name)
{
	return fit_parse_spec(spec,	//字符串"90080000"
							'#', addr_curr, addr, conf_name);
}
