	print_decomp_msg(comp, type, load == image_start, load);

	/*
	 * 将图像加载到正确的位置，如果需要，请解压缩。后
	 * this，image_len 将设置为未压缩字节数
	 * loaded，则 ret 在出错时将为非零。
	 */
	switch (comp) {
	case IH_COMP_NONE:
		ret = 0;
		if (load == image_start)
			break;
		if (image_len <= unc_len)
			memmove_wd(load_buf, image_buf, image_len, CHUNKSZ);
		else
			ret = -ENOSPC;
		break;
	}
}
