# cli_getch.c
## cli_ch_process 转义处理程序
```c
int cli_ch_process(struct cli_ch_state *cch, int ichar)
{
	/*
	 * ichar=0x0 当 U-Boot getchar（） 出现错误时或当调用者
	 * 想要检查转义中是否保存了更多字符序列
	 */
	if (!ichar) {
		if (cch->emitting) {
			if (cch->emit_upto < cch->esc_len)
				return cch->esc_save[cch->emit_upto++];
			cch->emit_upto = 0;
			cch->emitting = false;
			cch->esc_len = 0;
		}
		return 0;
	} else if (ichar == -ETIMEDOUT) {
		/*
		 * 如果我们在转义序列中，但没有任何内容遵循
		 * 转义字符，则用户可能只是按下了
		 * 退出键。返回它并清除序列。
		 */
		if (cch->esc_len) {	//到目前为止读取的转义字符数
			cch->esc_len = 0;
			return '\e';
		}

		/* Otherwise there is nothing to return */
		return 0;
	}

	if (ichar == '\n' || ichar == '\r')
		return '\n';

	/* 处理标准 Linux xTerm ESC 序列，用于箭头键等 */
	if (cch->esc_len != 0) {
		enum cli_esc_state_t act;
		//处理转义字符 act:是否转义完成,ichar:转义后的字符
		ichar = cli_ch_esc(cch, ichar, &act);

		switch (act) {
		case ESC_SAVE:
			/* 保存此字符，不返回任何内容 */
			cch->esc_save[cch->esc_len++] = ichar;
			ichar = 0;
			break;
		case ESC_REJECT:
			/*
			 * 无效的转义序列 的 start 返回 其中的字符
			 */
			cch->esc_save[cch->esc_len++] = ichar;
			ichar = cch->esc_save[cch->emit_upto++];	//要从 esc_save 发出的下一个索引
			cch->emitting = true;	//是从 esc_save 发出的字符
			return ichar;
		case ESC_CONVERTED:
			/*有效的转义序列返回生成的 char*/
			cch->esc_len = 0;
			break;
		}
	}
	//检查变量 ichar 是否等于转义字符 '\e'
	if (ichar == '\e') {
		if (!cch->esc_len) {	//如果没有转义字符
			cch->esc_save[cch->esc_len] = ichar;	//保存转义字符
			cch->esc_len = 1;	//转义字符长度为1
		} else {
			puts("impossible condition #876\n");
			cch->esc_len = 0;
		}
		return 0;
	}

	return ichar;
}
```

## cli_ch_esc 处理转义字符
```c
/**
 * enum cli_esc_state_t - 指示如何处理转义字符
 *
 * @ESC_REJECT：转义序列无效，因此 esc_save[] 字符为
 * 从每次后续调用 cli_ch_esc（） 返回
 * @ESC_SAVE：字符应保存在 esc_save 中，直到我们有另一个字符
 * @ESC_CONVERTED：转义序列已完成，生成的
 * 字符可用
 */
enum cli_esc_state_t {
	ESC_REJECT,
	ESC_SAVE,
	ESC_CONVERTED
};
static int cli_ch_esc(struct cli_ch_state *cch, int ichar,
		      enum cli_esc_state_t *actp)
{
	enum cli_esc_state_t act = ESC_REJECT;

	switch (cch->esc_len) {
	case 1:
		if (ichar == '[' || ichar == 'O')
			act = ESC_SAVE;
		else
			act = ESC_CONVERTED
		break;
	case 2:
		switch (ichar) {
		case 'D':	/* <- key */
			ichar = CTL_CH('b');
			act = ESC_CONVERTED;
			break;	/* pass off to ^B handler */
		case 'C':	/* -> key */
			ichar = CTL_CH('f');
			act = ESC_CONVERTED;
			break;	/* pass off to ^F handler */
		case 'H':	/* Home key */
			ichar = CTL_CH('a');
			act = ESC_CONVERTED;
			break;	/* pass off to ^A handler */
		case 'F':	/* End key */
			ichar = CTL_CH('e');
			act = ESC_CONVERTED;
			break;	/* pass off to ^E handler */
		case 'A':	/* up arrow */
			ichar = CTL_CH('p');
			act = ESC_CONVERTED;
			break;	/* pass off to ^P handler */
		case 'B':	/* down arrow */
			ichar = CTL_CH('n');
			act = ESC_CONVERTED;
			break;	/* pass off to ^N handler */
		case '1':
		case '2':
		case '3':
		case '4':
		case '7':
		case '8':
			if (cch->esc_save[1] == '[') {
				/*看看下一个角色是不是 ~ */
				act = ESC_SAVE;
			}
			break;
		}
		break;
	case 3:
		switch (ichar) {
		case '~':
			switch (cch->esc_save[2]) {
			case '3':	/* Delete key */
				ichar = CTL_CH('d');
				act = ESC_CONVERTED;
				break;	/* pass to ^D handler */
			case '1':	/* Home key */
			case '7':
				ichar = CTL_CH('a');
				act = ESC_CONVERTED;
				break;	/* pass to ^A handler */
			case '4':	/* End key */
			case '8':
				ichar = CTL_CH('e');
				act = ESC_CONVERTED;
				break;	/* pass to ^E handler */
			}
			break;
		case '0':
			if (cch->esc_save[2] == '2')
				act = ESC_SAVE;
			break;
		}
		break;
	case 4:
		switch (ichar) {
		case '0':
		case '1':
			act = ESC_SAVE;
			break;		/* bracketed paste */
		}
		break;
	case 5:
		if (ichar == '~') {	/* bracketed paste */
			ichar = 0;
			act = ESC_CONVERTED;
		}
	}

	*actp = act;

	return ichar;
}
```

