	int ret;
    //寻找当前节点的`resets`的phandle索引,内容为`#reset-cells`的设备节点
	ret = dev_read_phandle_with_args(dev, "resets", "#reset-cells", 0,
					 index, &args);

	return reset_get_by_index_tail(ret, dev_ofnode(dev), &args, "resets",
				       index > 0, reset_ctl);
}
