## STM32_PINMUX 引脚宏定义
```c
/*  define PIN modes */
/*
AF0：系统功能，如事件输出、RTC 时钟输出等。
AF1：TIM1 和 TIM2 的输入/输出。
AF2：TIM3 到 TIM5 的输入/输出。
AF3：TIM8 到 TIM11 的输入/输出。
AF4：I2C1 到 I2C4 的数据和时钟线。
AF5：SPI1、SPI2、SPI3 和 I2S 的数据和时钟线。
AF6：SPI3 和 I2S 的数据和时钟线。
AF7：USART1 到 USART3 的数据和控制线。
AF8：UART4 到 UART8 的数据和控制线。
AF9：CAN1 和 CAN2 的数据和控制线。
AF10：USB OTG FS/HS 的数据和控制线。
AF11：以太网的控制和数据线。
AF12：FSMC、SDIO 和 OTG HS 的数据和控制线。
AF13：DCMI 的数据和控制线。
AF14：LCD 的数据和控制线。
AF15：事件输出。
*/
#define GPIO	0x0
#define AF0	0x1
#define AF1	0x2
#define AF2	0x3
#define AF3	0x4
#define AF4	0x5
#define AF5	0x6
#define AF6	0x7
#define AF7	0x8
#define AF8	0x9
#define AF9	0xa
#define AF10	0xb
#define AF11	0xc
#define AF12	0xd
#define AF13	0xe
#define AF14	0xf
#define AF15	0x10
#define ANALOG	0x11

/* define Pins number*/
#define PIN_NO(port, line)	(((port) - 'A') * 0x10 + (line))

#define STM32_PINMUX(port, line, mode) (((PIN_NO(port, line)) << 8) | (mode))
