## fdt_ro.c
### fdt_path_offset_namelen 查找路径的偏移量
```c
int fdt_path_offset_namelen(const void *fdt, const char *path, int namelen)
{
	const char *end = path + namelen;
	const char *p = path;
	int offset = 0;

	FDT_RO_PROBE(fdt);

	//检查是否有别名
	if (*path != '/') {
		const char *q = memchr(path, '/', end - p);

		if (!q)
			q = end;
		//查找别名对应的实际路径
		p = fdt_get_alias_namelen(fdt, p, q - p);   // fdt_path_offset(fdt, "/aliases");
		if (!p)
			return -FDT_ERR_BADPATH;
		offset = fdt_path_offset(fdt, p);

		p = q;
	}
	//遍历路径
	while (p < end) {
		const char *q;
		//处理路径中的斜杠
		while (*p == '/') {
			p++;
			if (p == end)
				return offset;
		}
		//查找下一个斜杠
		q = memchr(p, '/', end - p);
		if (! q)	//没有找到斜杠
			q = end;	//则指向路径末尾
		//查找路径节点的偏移量
		offset = fdt_subnode_offset_namelen(fdt, offset, p, q-p);
		if (offset < 0)
			return offset;

		p = q;
	}

	return offset;
}
```

### fdt_subnode_offset_namelen 查找子节点的偏移量
```c
/* fdt:设备树指针
 * offset:父节点的偏移量
 * name:子节点的名称
 * namelen:子节点名称的长度
 */
int fdt_subnode_offset_namelen(const void *fdt, int offset,
			       const char *name, int namelen)
{
	int depth;

	FDT_RO_PROBE(fdt);

	for (depth = 0;
	     (offset >= 0) && (depth >= 0);
	     offset = fdt_next_node(fdt, offset, &depth))   //查找下一个节点
		if ((depth == 1)    //深度为1,达到子节点
		    && fdt_nodename_eq_(fdt, offset, name, namelen))    //比较节点名称正确
			return offset;  //返回子节点的偏移量

	if (depth < 0)
		return -FDT_ERR_NOTFOUND;
	return offset; /* error */
}
