			if (!lists_bind_fdt(dm_root(), node, &dev, NULL, false)) {
				ret = device_probe(dev);	//执行设备的probe函数
				if (ret)
					return ret;
			}
		}
	}

	if (!dev) {
		/*回退到第一个可用时间,并执行device_probe*/
		ret = uclass_first_device_err(UCLASS_TIMER, &dev);
		if (ret)
			return ret;
	}

	if (dev) {
		gd->timer = dev;
		return 0;
	}

	return -ENODEV;
}
