# env.c
- 从其他存储位置加载环境变量
- 其他地方没有存储则执行默认的环境变量
- 这样可以在使用在其他地方配置好环境变量,然后在u-boot中直接使用

## env_init
```c
int env_init(void)
{
    struct env_driver *drv;
    int ret = -ENOENT;
    int prio;
    // 从优先级0开始查找环境驱动,直到没有环境驱动
    for (prio = 0; (drv = env_driver_lookup(ENVOP_INIT, prio)); prio++) {
        // 如果环境驱动的init函数存在,则调用init函数
        if (!drv->init || !(ret = drv->init())) // 如果初始化成功
            env_set_inited(drv->location);
        if (ret == -ENOENT) // 如果不需要初始化
            env_set_inited(drv->location);  //gd->env_has_init |= BIT(location);

        debug("%s: Environment %s init done (ret=%d)\n", __func__,
              drv->name, ret);

        if (gd->env_valid == ENV_INVALID)
            ret = -ENOENT;
    }
    // 如果没有找到环境驱动,则返回-ENOENT
    if (!prio)
        return -ENODEV;
    // 找到了环境驱动,但是环境无效,则使用默认环境
    if (ret == -ENOENT) {
        gd->env_addr = (ulong)&default_environment[0];
        gd->env_valid = ENV_VALID;

        return 0;
    }

    return ret;
}
```

## env_driver_lookup
- 根据优先级和操作查找环境驱动并返回
```c
static struct env_driver *env_driver_lookup(enum env_operation op, int prio)
{
    enum env_location loc = env_get_location(op, prio);
    struct env_driver *drv;

    if (loc == ENVL_UNKNOWN)
        return NULL;

    drv = _env_driver_lookup(loc);
    if (!drv) {
        debug("%s: No environment driver for location %d\n", __func__,
              loc);
        return NULL;
    }

    return drv;
}
```

## arch_env_get_location
- 根据优先级返回环境位置
```c
__weak enum env_location arch_env_get_location(enum env_operation op, int prio)
{
    if (prio >= ARRAY_SIZE(env_locations))
        return ENVL_UNKNOWN;

    return env_locations[prio];
}
```

## _env_driver_lookup
- 在段中查找环境驱动,匹配符合的环境位置
```c
static struct env_driver *_env_driver_lookup(enum env_location loc)
{
    struct env_driver *drv;
    const int n_ents = ll_entry_count(struct env_driver, env_driver);
    struct env_driver *entry;

    drv = ll_entry_start(struct env_driver, env_driver);
    for (entry = drv; entry != drv + n_ents; entry++) {
        if (loc == entry->location)
            return entry;
    }

    /* Not found */
    return NULL;
}
```

# common.c
## env_get_from_linear
```c
static int env_get_from_linear(const char *env, const char *name, char *buf,
                   unsigned len)
{
    const char *p, *end;
    size_t name_len;

    if (name == NULL || *name == '\0')
        return -1;

    name_len = strlen(name);

    for (p = env; *p != '\0'; p = end + 1) {
        const char *value;
        unsigned res;
        //识别到数组结束符
        for (end = p; *end != '\0'; ++end)
            if (end - env >= CONFIG_ENV_SIZE)
                return -1;

        if (strncmp(name, p, name_len) || p[name_len] != '=')
            continue;
        //找到name
        value = &p[name_len + 1];

        res = end - value;
        //拷贝环境变量的值
        memcpy(buf, value, min(len, res + 1));

        if (len <= res) {
            buf[len - 1] = '\0';
            printf("env_buf [%u bytes] too small for value of \"%s\"\n",
                   len, name);
        }

        return res;
    }

    return -1;
}
