        //没有值,则少个参数传入,所以是2
        //执行删除操作
		return env_do_env_set(0, 2, (char * const *)argv, H_PROGRAMMATIC);
	else
        //有值,则多一个参数传入,所以是3
		//执行设置操作
        return env_do_env_set(0, 3, (char * const *)argv, H_PROGRAMMATIC);
}
