# drivers/pinctrl/core.c
## devm_pinctrl_register: 自动管理资源的pinctrl设备注册函数

此函数是标准`pinctrl_register`函数的一个"设备资源管理"(`devm`)版本。它的核心作用与`pinctrl_register`完全相同: 将一个驱动程序描述的引脚控制器(`pinctldesc`)注册到Linux内核的pinctrl子系统中, 使其对系统可用。

其与标准版本的根本区别在于**资源生命周期管理**。此函数的原理是利用Linux设备模型的`devres`(Device Resource)框架, 将pinctrl设备的释放操作与父设备(`dev`)的生命周期自动绑定。

具体工作流程如下:
1.  **分配管理句柄**: 函数首先调用`devres_alloc`分配一小块内存(`ptr`)。这块内存被注册为`dev`设备的一个受管资源, 并与一个"释放函数"(`devm_pinctrl_dev_release`)关联起来。
2.  **执行标准注册**: 接着, 它调用底层的`pinctrl_register`函数来执行实际的注册工作, 创建`pinctrl_dev`实例。
3.  **保存并激活管理**: 如果`pinctrl_register`成功, 它会将返回的`pinctrl_dev`指针保存到第一步分配的受管内存块`ptr`中, 然后调用`devres_add`正式将其加入到`dev`设备的资源管理链表中。
4.  **自动释放**: 此后, 驱动程序本身不再需要关心pinctrl设备的释放。当`dev`设备被卸载或驱动被解除绑定时, 内核的设备模型会自动遍历其`devres`链表, 并调用之前注册的`devm_pinctrl_dev_release`函数, 该函数内部会调用`pinctrl_unregister`来完成所有清理工作。

对于STM32H750这样的嵌入式系统, 使用`devm_`系列的函数是推荐的最佳实践。它极大地简化了驱动程序的错误处理流程。在复杂的探测函数(如`stm32_pctl_probe`)中, 如果有任何一步失败, 驱动开发者无需编写繁琐的`goto`链来反向注销已经成功注册的资源, `devm`框架会自动处理这一切, 从而使得代码更简洁、更健壮, 并能有效防止因错误处理不当导致的资源泄漏。

```c
/**
 * devm_pinctrl_register() - pinctrl_register() 的资源管理版本.
 * @dev: 此引脚控制器的父设备
 * @pctldesc: 此引脚控制器的描述符
 * @driver_data: 此引脚控制器的私有数据
 *
 * 如果引脚控制器注册失败, 返回一个错误指针. 否则,
 * 返回一个有效的 pinctrl 句柄.
 *
 * 当设备被解除绑定时, 这个 pinctrl 设备将会被自动释放.
 */
struct pinctrl_dev *devm_pinctrl_register(struct device *dev,
					  const struct pinctrl_desc *pctldesc,
					  void *driver_data)
{
	/*
	 * 定义一个指向 "pinctrl_dev 指针" 的指针 ptr.
	 * 定义一个指向 pinctrl_dev 的指针 pctldev.
	 */
	struct pinctrl_dev **ptr, *pctldev;

	/*
	 * 调用 devres_alloc 分配一个 devres 资源记录.
	 * - 第一个参数 devm_pinctrl_dev_release 是一个释放函数. 当 dev 设备被解绑时, 内核会自动调用此函数.
	 * - 第二个参数 sizeof(*ptr) 是要为该记录分配的内存大小, 这里是 sizeof(struct pinctrl_dev *), 即一个指针的大小.
	 * - 第三个参数 GFP_KERNEL 是标准的内存分配标志.
	 */
	ptr = devres_alloc(devm_pinctrl_dev_release, sizeof(*ptr), GFP_KERNEL);
	/*
	 * 如果 devres 记录分配失败, 返回内存不足错误.
	 */
	if (!ptr)
		return ERR_PTR(-ENOMEM);

	/*
	 * 调用底层的、非资源管理的 pinctrl_register 函数来执行实际的注册工作.
	 * 它会创建一个 pinctrl_dev 实例并返回其指针.
	 */
	pctldev = pinctrl_register(pctldesc, dev, driver_data);
	/*
	 * 检查 pinctrl_register 是否返回了错误.
	 */
	if (IS_ERR(pctldev)) {
		/*
		 * 如果注册失败, 那么我们之前分配的 devres 记录就不需要了, 调用 devres_free 将其释放.
		 */
		devres_free(ptr);
		/*
		 * 将原始的错误指针返回给调用者.
		 */
		return pctldev;
	}

	/*
	 * 将成功创建的 pctldev 指针存入 devres 记录的内存中 (*ptr = ...).
	 * 这样, 当释放函数 devm_pinctrl_dev_release 被调用时, 它就可以得到这个 pctldev 指针.
	 */
	*ptr = pctldev;
	/*
	 * 调用 devres_add, 将这个已填充好数据的 devres 记录正式添加到 dev 设备的资源列表中.
	 * 从这一刻起, 内核就接管了这个资源的生命周期.
	 */
	devres_add(dev, ptr);

	/*
	 * 将成功的 pctldev 句柄返回给调用者.
	 */
	return pctldev;
}
/*
 * 将 devm_pinctrl_register 函数导出, 使其对其他遵循GPL许可证的内核模块可用.
 * 这是内核API的标准做法.
 */
EXPORT_SYMBOL_GPL(devm_pinctrl_register);
```

## pinctrl_register_pins 和 pinctrl_register_one_pin: 注册引脚

这两个函数是pinctrl设备初始化过程中负责处理"引脚"注册的核心实现。`pinctrl_register_pins`是一个上层封装, 它通过循环调用`pinctrl_register_one_pin`来完成工作。它们共同的原理是: **为驱动程序提供的每一个物理引脚, 在内核中创建一个对应的、更详细的内部描述符(`struct pin_desc`), 并将其插入到pinctrl设备的基数树(`radix_tree`)中, 以便日后能够通过引脚编号快速地查找到它。**

---

### `pinctrl_register_one_pin`: 注册单个引脚

此函数负责将一个引脚的描述信息注册到内核。

```c
/*
 * 静态函数声明: pinctrl_register_one_pin
 * 此函数仅在当前文件中可见.
 * @pctldev: 指向 struct pinctrl_dev 的指针, 引脚将被注册到这个控制器下.
 * @pin: 指向 const struct pinctrl_pin_desc 的指针, 这是驱动提供的、关于单个引脚的描述.
 * @return: 成功时返回 0, 失败时返回负的错误码.
 */
static int pinctrl_register_one_pin(struct pinctrl_dev *pctldev,
				    const struct pinctrl_pin_desc *pin)
{
	/*
	 * 定义一个指向 struct pin_desc 的指针 pindesc.
	 * pin_desc 是pinctrl核心在内部用来表示一个引脚的结构体, 它比驱动提供的 pinctrl_pin_desc 包含更多信息.
	 */
	struct pin_desc *pindesc;
	int error;

	/*
	 * 调用 pin_desc_get, 检查此引脚编号是否已经被注册过.
	 * pin_desc_get 内部会查询 pctldev->pin_desc_tree 基数树.
	 */
	/* static inline struct pin_desc *pin_desc_get(struct pinctrl_dev *pctldev,
					    unsigned int pin)
	{
		return radix_tree_lookup(&pctldev->pin_desc_tree, pin);
	} */
	pindesc = pin_desc_get(pctldev, pin->number);
	if (pindesc) {
		/*
		 * 如果 pindesc 不为NULL, 说明该引脚号已被占用, 这是一个错误.
		 */
		dev_err(pctldev->dev, "pin %d already registered\n",
			pin->number);
		return -EINVAL; // 返回无效参数错误.
	}

	/*
	 * 为内核内部的 pin_desc 结构体分配内存并清零.
	 */
	pindesc = kzalloc(sizeof(*pindesc), GFP_KERNEL);
	if (!pindesc)
		return -ENOMEM;

	/* 设置所有者, 将内部描述符与 pinctrl 设备关联起来. */
	pindesc->pctldev = pctldev;
#ifdef CONFIG_PINMUX
	/* 如果内核配置了PINMUX, 则为该引脚初始化一个互斥锁.
	 * 这个锁 (pindesc->mux_lock) 将用于保护对该引脚复用状态的并发访问.
	 * 在单核抢占式系统上, 它可以防止在配置引脚时被其他任务抢占.
	 */
	mutex_init(&pindesc->mux_lock);
#endif

	/* 复制基本的引脚信息 */
	if (pin->name) {
		/*
		 * 如果驱动为引脚提供了一个名称, 直接使用该名称的指针.
		 */
		pindesc->name = pin->name;
	} else {
		/*
		 * 如果驱动没有提供名称, 内核会自动生成一个, 格式为 "PIN<编号>".
		 * kasprintf 会动态分配内存来存储这个生成的名称.
		 */
		pindesc->name = kasprintf(GFP_KERNEL, "PIN%u", pin->number);
		if (!pindesc->name) {
			error = -ENOMEM;
			goto failed; // 内存分配失败, 跳转到错误清理.
		}
		/*
		 * 设置一个标志, 表明这个名称是动态分配的, 在释放时需要被 kfree.
		 */
		pindesc->dynamic_name = true;
	}

	/*
	 * 复制驱动可能为该引脚提供的私有数据.
	 */
	pindesc->drv_data = pin->drv_data;

	/*
	 * 这是最核心的一步: 将新创建的 pindesc 插入到基数树中.
	 * - &pctldev->pin_desc_tree: 目标基数树.
	 * - pin->number: 键(key), 即引脚的编号.
	 * - pindesc: 值(value), 即指向内核内部描述符的指针.
	 * 此后, 内核就可以通过引脚号快速查找到 pindesc.
	 */
	error = radix_tree_insert(&pctldev->pin_desc_tree, pin->number, pindesc);
	if (error)
		goto failed; // 插入失败, 跳转到错误清理.

	/*
	 * 打印一条调试信息, 记录哪个引脚被注册到了哪个控制器上.
	 */
	pr_debug("registered pin %d (%s) on %s\n",
		 pin->number, pindesc->name, pctldev->desc->name);
	return 0; // 成功.

failed:
	/*
	 * 统一的错误处理出口.
	 * 释放为 pindesc 分配的内存. 注意: 如果 pindesc->name 是动态分配的, 这里会造成内存泄漏.
	 * (这是一个内核代码中的小缺陷, 现代内核可能已经修复. 正常情况下, 应该先判断并释放 dynamic_name).
	 */
	kfree(pindesc);
	return error; // 返回错误码.
}
```

### `pinctrl_register_pins`: 注册一个引脚数组

此函数是一个简单的循环封装, 用于注册一个驱动程序提供的所有引脚。

```c
/*
 * 静态函数声明: pinctrl_register_pins
 * 此函数仅在当前文件中可见.
 * @pctldev: 指向 struct pinctrl_dev 的指针, 引脚将被注册到这个控制器下.
 * @pins: 指向一个 pinctrl_pin_desc 结构体数组的指针.
 * @num_descs: 数组中元素的数量.
 * @return: 成功时返回 0, 任何一次注册失败都会立即返回错误码.
 */
static int pinctrl_register_pins(struct pinctrl_dev *pctldev,
				 const struct pinctrl_pin_desc *pins,
				 unsigned int num_descs)
{
	/*
	 * 定义一个无符号整型 i 作为循环计数器.
	 */
	unsigned int i;
	int ret = 0;

	/*
	 * 循环遍历驱动提供的所有引脚描述符.
	 */
	for (i = 0; i < num_descs; i++) {
		/*
		 * 调用 pinctrl_register_one_pin 来注册数组中的第 i 个引脚.
		 */
		ret = pinctrl_register_one_pin(pctldev, &pins[i]);
		if (ret)
			/*
			 * 如果任何一个引脚注册失败, 立即停止并返回错误码.
			 * 这确保了注册过程的原子性: 要么全部成功, 要么在第一个失败处停止.
			 */
			return ret;
	}

	/*
	 * 所有引脚都成功注册.
	 */
	return 0;
}
```

## pinctrl_init_controller: 初始化一个引脚控制器

此函数是pinctrl设备注册流程的第一阶段和内部核心。它是一个静态函数, 意味着它只在pinctrl核心代码内部被调用(由`pinctrl_register`调用)。它的核心原理是**分配并填充内核用来代表一个引脚控制器的通用数据结构(`struct pinctrl_dev`), 并对驱动程序提供的操作函数集进行合法性检查, 最后将驱动提供的所有引脚信息注册到内部的快速查找数据结构中**。

简而言之, 这个函数负责在内存中构建一个pinctrl设备的完整软件映像, 但**不**会将其"激活"或暴露给系统其他部分。它完成了所有准备工作。

具体流程如下:
1.  **参数验证与内存分配**: 首先, 它会验证驱动程序提供的描述符(`pctldesc`)及其名称是否有效。然后, 它使用`kzalloc`为`struct pinctrl_dev`分配一块被清零的内存。
2.  **数据结构初始化**: 接着, 它会填充`pinctrl_dev`结构体的各个字段, 包括从`pctldesc`中复制过来的信息、父设备指针和驱动私有数据指针。同时, 它会初始化该结构体内部的多个重要数据成员, 包括:
    *   `mutex`: 一个互斥锁, 用于保护该控制器实例的数据在并发访问时的一致性。在STM32H750这样的单核抢占式系统上, 它可以防止一个任务在操作控制器数据时被另一个任务抢占。
    *   `Radix Tree`: 初始化多个基数树。基数树是一种内存效率很高的查找树, 内核在这里用它来存储所有的引脚、引脚组和功能信息, 以便后续能够通过它们的数字ID进行快速查找。
    *   链表头: 初始化多个链表头, 以备后续使用。
3.  **操作函数合法性检查**: 它会进行一系列严格的检查, 确保驱动提供的操作函数集(`pctlops`, `pmxops`, `confops`)是完整且有效的。例如, 如果一个驱动声称支持pinmux功能, 那么它必须提供`get_functions_count`等一系列必要的`pmxops`函数。如果检查不通过, 初始化就会失败, 这可以防止有缺陷的驱动被注册。
4.  **引脚注册**: 这是最关键的步骤之一。它调用`pinctrl_register_pins`, 遍历驱动在`pctldesc->pins`中提供的所有引脚, 并将它们一一添加到之前初始化的`pin_desc_tree`基数树中。完成这一步后, 内核就可以通过引脚编号快速地找到任何一个引脚的描述信息。
5.  **错误处理**: 函数使用了`goto`标签来进行统一的错误清理。如果在内存分配之后的任何步骤发生错误, 程序会跳转到`out_err`, 在那里它会销毁已初始化的互斥锁, 释放为`pctldev`分配的内存, 并返回一个标准的错误指针。

```c
/**
 * pinctrl_init_controller() - 初始化一个引脚控制器设备
 * @pctldesc: 此引脚控制器的描述符
 * @dev: 此引脚控制器的父设备
 * @driver_data: 此引脚控制器的私有数据
 */
static struct pinctrl_dev *
pinctrl_init_controller(const struct pinctrl_desc *pctldesc, struct device *dev,
			void *driver_data)
{
	struct pinctrl_dev *pctldev;
	int ret;

	/*
	 * 检查传入的描述符指针是否有效.
	 */
	if (!pctldesc)
		return ERR_PTR(-EINVAL);
	/*
	 * 检查描述符中的名称字段是否有效, 每个控制器都必须有一个名字.
	 */
	if (!pctldesc->name)
		return ERR_PTR(-EINVAL);

	/*
	 * 为 pinctrl_dev 结构体分配内存并清零.
	 * pinctrl_dev 是内核中代表一个引脚控制器的通用结构.
	 * GFP_KERNEL 标志允许在内存不足时让当前进程睡眠等待.
	 */
	pctldev = kzalloc(sizeof(*pctldev), GFP_KERNEL);
	if (!pctldev)
		return ERR_PTR(-ENOMEM);

	/* 初始化引脚控制器设备结构体 */
	pctldev->owner = pctldesc->owner; // 记录拥有此驱动的模块.
	pctldev->desc = pctldesc;         // 保存指向驱动提供的描述符的指针.
	pctldev->driver_data = driver_data; // 保存指向驱动私有数据的指针.
	/* 初始化用于快速查找引脚描述符的基数树. */
	INIT_RADIX_TREE(&pctldev->pin_desc_tree, GFP_KERNEL);
#ifdef CONFIG_GENERIC_PINCTRL_GROUPS
	/* 如果配置了通用引脚组, 则初始化引脚组的基数树. */
	INIT_RADIX_TREE(&pctldev->pin_group_tree, GFP_KERNEL);
#endif
#ifdef CONFIG_GENERIC_PINMUX_FUNCTIONS
	/* 如果配置了通用引脚复用功能, 则初始化功能函数的基数树. */
	INIT_RADIX_TREE(&pctldev->pin_function_tree, GFP_KERNEL);
#endif
	/* 初始化用于管理GPIO范围的链表头. */
	INIT_LIST_HEAD(&pctldev->gpio_ranges);
	/* 初始化用于将此设备加入全局pinctrl设备列表的链表节点. */
	INIT_LIST_HEAD(&pctldev->node);
	pctldev->dev = dev;               // 保存指向父设备的指针.
	/* 初始化用于保护此控制器内部数据的互斥锁. */
	mutex_init(&pctldev->mutex);

	/* 检查核心操作函数的完整性. */
	ret = pinctrl_check_ops(pctldev);
	if (ret) {
		dev_err(dev, "pinctrl ops lacks necessary functions\n");
		goto out_err;
	}

	/* 如果驱动实现了 pinmuxing, 检查其操作函数的完整性. */
	if (pctldesc->pmxops) {
		ret = pinmux_check_ops(pctldev);
		if (ret)
			goto out_err;
	}

	/* 如果驱动实现了 pinconfig, 检查其操作函数的完整性. */
	if (pctldesc->confops) {
		ret = pinconf_check_ops(pctldev);
		if (ret)
			goto out_err;
	}

	/* 注册所有引脚. */
	dev_dbg(dev, "try to register %d pins ...\n",  pctldesc->npins);
	/* 调用 pinctrl_register_pins 将所有引脚添加到 pin_desc_tree 中. */
	ret = pinctrl_register_pins(pctldev, pctldesc->pins, pctldesc->npins);
	if (ret) {
		dev_err(dev, "error during pin registration\n");
		/* 如果注册引脚失败, 需要释放已经为引脚描述符复制的内存. */
		pinctrl_free_pindescs(pctldev, pctldesc->pins,
				      pctldesc->npins);
		goto out_err;
	}

	/* 初始化成功, 返回指向 pinctrl_dev 结构体的指针. */
	return pctldev;

/* 统一的错误处理出口. */
out_err:
	/* 销毁之前初始化的互斥锁. */
	mutex_destroy(&pctldev->mutex);
	/* 释放为 pinctrl_dev 结构体分配的内存. */
	kfree(pctldev);
	/* 返回一个编码为指针的错误码. */
	return ERR_PTR(ret);
}
```

## create_pinctrl: 为设备创建pinctrl句柄

此函数是pinctrl子系统中的一个核心工厂函数。它的作用是为一个特定的设备(消费者,`dev`), 创建一个`struct pinctrl`实例。这个实例可以被看作是该设备与整个pinctrl子系统之间的一个"会话"或"句柄"。它聚合了所有与该设备相关的引脚配置信息, 无论是从设备树(Device Tree)中解析的, 还是从传统的基于平台的映射表中找到的。这个函数返回的`pinctrl`指针, 正是驱动程序调用`pinctrl_get()`时最终获得的对象。

其核心原理是一个两阶段的"映射-聚合"过程:
1.  **从设备树解析**: 函数首先调用`pinctrl_dt_to_map`, 直接解析消费者设备`dev`自己的设备树节点。它会查找`pinctrl-0`, `pinctrl-1`, `pinctrl-names`等标准属性, 并将它们转换成内核内部的`pinctrl_map`格式, 暂存到新建的`pinctrl`句柄中。
2.  **从全局映射表查找**: 接着, 它会遍历一个全局的、包含了所有(包括非设备树方式注册的)引脚映射表的链表。在这个遍历过程中, 它会进行匹配:
    *   **设备匹配**: 确保映射表是为当前设备`dev`准备的。
    *   **控制器匹配**: 在处理"pin hog"的特殊情况下(即`pctldev`不为NULL), 它会额外确保映射表是由`pctldev`这个控制器提供的, 从而避免一个pinctrl驱动错误地霸占由另一个控制器管理的引脚。
3.  **聚合设置**: 对于每一个成功匹配的映射, 函数会调用`add_setting`。这个辅助函数负责查找具体的引脚组和功能, 并创建一个"设置(setting)"对象, 将其链接到`pinctrl`句柄的状态列表中。
4.  **依赖处理**: 这个过程优雅地处理了驱动加载顺序问题。如果`add_setting`发现某个引脚配置所需的pinctrl控制器驱动尚未加载, 它会返回`-EPROBE_DEFER`。`create_pinctrl`捕捉到这个错误后, 会清理所有已分配的资源, 并将`-EPROBE_DEFER`传播出去, 通知内核稍后重试。

在STM32H750这样的单核抢占式系统上, 此函数中使用的全局互斥锁(`pinctrl_maps_mutex`和`pinctrl_list_mutex`)至关重要。它们确保了在遍历或修改全局的映射表链表和pinctrl句柄链表时, 不会被另一个任务抢占, 从而防止了对这些共享资源的并发访问, 保证了数据结构的完整性。

```c
/*
 * 静态函数声明: create_pinctrl
 * 为一个设备创建 pinctrl 句柄.
 * @dev: 消费者设备 (例如一个I2C驱动对应的设备).
 * @pctldev: 提供服务的引脚控制器设备. 在处理 pin hog 时, dev 和 pctldev->dev 是同一个设备.
 * @return: 成功时返回一个有效的 pinctrl 句柄, 失败时返回错误指针.
 */
static struct pinctrl *create_pinctrl(struct device *dev,
				      struct pinctrl_dev *pctldev)
{
	struct pinctrl *p;
	const char *devname;
	struct pinctrl_maps *maps_node;
	const struct pinctrl_map *map;
	int ret;

	/*
	 * 为每个映射关系创建一个 pinctrl 结构体, 这是一个状态"cookie"的持有者.
	 * 消费者调用 pinctrl_get() 时获取到的就是这个结构体.
	 */
	p = kzalloc(sizeof(*p), GFP_KERNEL);
	if (!p)
		return ERR_PTR(-ENOMEM);
	p->dev = dev; // 关联到消费者设备.
	INIT_LIST_HEAD(&p->states); // 初始化状态列表.
	INIT_LIST_HEAD(&p->dt_maps); // 初始化设备树映射列表.

	/*
	 * 调用 pinctrl_dt_to_map, 解析设备 dev 的设备树节点, 将 pinctrl-* 属性转换成内部的映射表.
	 */
	ret = pinctrl_dt_to_map(p, pctldev);
	if (ret < 0) {
		kfree(p);
		return ERR_PTR(ret);
	}

	/*
	 * 获取消费者设备的名称, 用于后续的匹配.
	 */
	devname = dev_name(dev);

	/*
	 * 锁定全局的 pinctrl 映射表互斥锁, 以安全地遍历.
	 */
	mutex_lock(&pinctrl_maps_mutex);
	/* 遍历全局的引脚控制映射表. */
	for_each_pin_map(maps_node, map) {
		/* 映射必须是为当前设备准备的. 如果设备名不匹配, 则跳过. */
		if (strcmp(map->dev_name, devname))
			continue;
		/*
		 * 如果 pctldev 不为 NULL, 说明我们正在为 pctldev 自身申请 hog 配置.
		 * 这意味着这个配置是由 pctldev 自己来服务的.
		 * 因此, 我们必须跳过那些虽然是为本设备(dev), 但却是由其他控制器(ctrl_dev_name)服务的映射.
		 */
		if (pctldev &&
		    strcmp(dev_name(pctldev->dev), map->ctrl_dev_name))
			continue;

		/*
		 * 为这个匹配的映射添加一个配置"设置".
		 */
		ret = add_setting(p, pctldev, map);
		/*
		 * add_setting 的返回值处理:
		 * - 可能返回 -EPROBE_DEFER, 如果 pinctrl 设备尚未就绪.
		 * - 可能失败, 如果设备未就绪且该设置为 hog (hog必须立即生效, 不能推迟).
		 * 如果返回的错误不是 -EPROBE_DEFER, 我们会累积错误, 以防后续遇到更严重的 -EPROBE_DEFER.
		 */
		if (ret == -EPROBE_DEFER) {
			mutex_unlock(&pinctrl_maps_mutex);
			/* 如果需要推迟, 必须释放已分配的 pinctrl 句柄. */
			pinctrl_free(p, false);
			return ERR_PTR(ret);
		}
	}
	mutex_unlock(&pinctrl_maps_mutex);

	/*
	 * 检查是否有非 -EPROBE_DEFER 的错误发生.
	 */
	if (ret < 0) {
		/* 如果发生其他错误, 释放资源并返回错误. */
		pinctrl_free(p, false);
		return ERR_PTR(ret);
	}

	/*
	 * 初始化 pinctrl 句柄的引用计数器.
	 */
	kref_init(&p->users);

	/* 将 pinctrl 句柄添加到全局列表中. */
	mutex_lock(&pinctrl_list_mutex);
	list_add_tail(&p->node, &pinctrl_list);
	mutex_unlock(&pinctrl_list_mutex);

	/*
	 * 成功创建, 返回 pinctrl 句柄.
	 */
	return p;
}
```

## pinctrl状态查找函数

这两个函数共同构成了pinctrl子系统中用于查找特定引脚配置状态的核心逻辑。设备驱动程序(如SPI, I2C驱动)通过调用`pinctrl_lookup_state`来获取一个指向特定状态(如"default", "sleep")的句柄, `find_state`则是其内部使用的辅助搜索函数。

---

### find_state: 在pinctrl句柄中查找状态

这是一个内部静态函数, 其唯一的作用是在一个给定的pinctrl句柄(`p`)所拥有的状态链表中, 通过名称线性搜索一个特定的`pinctrl_state`。

```c
/*
 * 静态函数声明: find_state
 * 此函数仅在当前文件中可见, 是 pinctrl_lookup_state 的一个辅助函数.
 * @p: 指向 struct pinctrl 的指针, 这是设备驱动获取到的pinctrl客户端句柄, 它包含了该设备的所有状态.
 * @name: 指向要查找的状态名称字符串的指针, 例如 "default".
 * @return: 如果找到, 返回一个指向 struct pinctrl_state 的有效指针; 如果未找到, 返回 NULL.
 */
static struct pinctrl_state *find_state(struct pinctrl *p,
					const char *name)
{
	/*
	 * 定义一个指向 pinctrl_state 的指针 state, 用作循环变量.
	 */
	struct pinctrl_state *state;

	/*
	 * 使用内核标准的 list_for_each_entry 宏来遍历 p->states 链表.
	 * p->states 是一个链表头, 链接了所有为该设备 p 解析到的引脚状态 (通常来自设备树).
	 */
	list_for_each_entry(state, &p->states, node)
		/*
		 * 使用 strcmp 函数比较当前遍历到的状态的名称 (state->name) 和要查找的名称 (name).
		 * strcmp 在两个字符串相等时返回 0.
		 */
		if (!strcmp(state->name, name))
			/*
			 * 如果找到了匹配的名称, 立即返回指向该状态的指针.
			 */
			return state;

	/*
	 * 如果遍历完整个链表都没有找到匹配的名称, 则返回 NULL.
	 */
	return NULL;
}
```

### pinctrl_lookup_state: 查找并获取一个引脚控制状态句柄

这是一个导出给内核其他模块使用的API函数。设备驱动程序调用此函数来获取一个状态句柄, 以便后续可以通过`pinctrl_select_state`来应用该状态。它的核心原理是先尝试查找一个真实的状态, 如果找不到, 则根据内核配置提供一个"虚拟"的(dummy)状态或返回错误, 从而增加了系统的灵活性和调试能力。

```c
/**
 * pinctrl_lookup_state() - 从一个 pinctrl 句柄中检索一个状态句柄
 * @p: 要从中检索状态的 pinctrl 句柄
 * @name: 要检索的状态的名称
 */
struct pinctrl_state *pinctrl_lookup_state(struct pinctrl *p,
						 const char *name)
{
	struct pinctrl_state *state;

	/*
	 * 首先, 调用内部辅助函数 find_state 来查找具有指定名称的真实状态.
	 */
	state = find_state(p, name);
	/*
	 * 检查 find_state 的返回值. 如果 state 为 NULL, 说明没有找到真实的状态.
	 */
	if (!state) {
		/*
		 * 检查全局变量 pinctrl_dummy_state 是否被设置.
		 * 这个变量通常通过内核启动参数来设置, 主要用于调试或在设备树不完整时允许系统启动.
		 */
		if (pinctrl_dummy_state) {
			/*
			 * 如果允许使用虚拟状态, 打印一条调试信息.
			 */
			dev_dbg(p->dev, "using pinctrl dummy state (%s)\n",
				name);
			/*
			 * 调用 create_state 创建一个"虚拟"的状态. 这个状态除了名字匹配外,
			 * 不包含任何实际的引脚配置信息. 它只是为了让驱动程序能够获得一个有效的指针,
			 * 从而避免因找不到状态而probe失败.
			 */
			state = create_state(p, name);
		} else
			/*
			 * 如果不允许使用虚拟状态 (这是默认和生产环境中的行为),
			 * 则返回一个编码为指针的错误码 -ENODEV (无此设备),
			 * 明确地告知调用者, 所需的状态不存在.
			 */
			state = ERR_PTR(-ENODEV);
	}

	/*
	 * 返回找到的真实状态, 或者创建的虚拟状态, 或者一个错误指针.
	 * 调用者需要使用 IS_ERR() 宏来检查返回值的有效性.
	 */
	return state;
}
/*
 * 将 pinctrl_lookup_state 函数导出, 使其对其他遵循GPL许可证的内核模块可用.
 */
EXPORT_SYMBOL_GPL(pinctrl_lookup_state);
```

## Pinctrl 注册与使能核心

这个代码片段展示了Linux内核pinctrl子系统的核心注册流程。它由三个函数组成, 协同工作来初始化一个pinctrl设备, 处理静态引脚配置(pin-hogging), 并最终使其对系统其他部分可用。

---

### pinctrl_claim_hogs: 应用静态引脚配置

此函数的作用是在pinctrl设备注册时, 自动处理并应用在设备树中定义的"pin hog"配置。一个"pin hog"是一种机制, 允许pinctrl驱动程序自身在初始化时就“霸占”并配置一组引脚到某种特定状态, 而无需等待其他设备驱动来请求它们。这对于设置那些在整个系统生命周期内都保持不变的引脚(如I2C总线上固定的上拉电阻引脚)非常有用。

其原理如下:
1.  它首先为pinctrl设备自身创建一个"客户端句柄"(`pctldev->p`), 使得驱动可以像其他客户端一样与自己交互。
2.  它在设备树中查找名为`PINCTRL_STATE_DEFAULT` ("default") 和 `PINCTRL_STATE_SLEEP` ("sleep") 的引脚配置状态。
3.  如果找到了"default"状态, 它会立即调用`pinctrl_select_state`将这个配置应用到硬件上。
4.  它仅仅查找并保存"sleep"状态的句柄, 这个状态将由电源管理核心在系统进入睡眠时自动应用。
5.  如果设备树中没有定义任何hog配置, 这并非一个错误, 函数会正常返回。

在STM32H750系统上, 驱动开发者可以通过在pinctrl设备的设备树节点内定义子节点来使用此功能, 从而实现上电后对引脚的默认配置。

```c
/*
 * 静态函数声明: pinctrl_claim_hogs
 * 为一个 pinctrl 设备处理并应用其静态引脚配置 ("pin hogs").
 * @pctldev: 指向 pinctrl 设备的指针.
 * @return: 成功时返回 0, 失败时返回错误码.
 */
static int pinctrl_claim_hogs(struct pinctrl_dev *pctldev)
{
	/*
	 * 为 pinctrl 设备自身创建一个 pinctrl 客户端句柄.
	 * 这使得 pinctrl 驱动可以作为自己的客户端来配置自己的引脚.
	 */
	pctldev->p = create_pinctrl(pctldev->dev, pctldev);
	/*
	 * create_pinctrl 在找不到任何 hogging 节点时会返回 -ENODEV.
	 * 这不是一个致命错误, 只是表示没有需要静态配置的引脚.
	 */
	if (PTR_ERR(pctldev->p) == -ENODEV) {
		/*
		 * 打印一条调试信息.
		 */
		dev_dbg(pctldev->dev, "no hogs found\n");

		/*
		 * 正常返回 0.
		 */
		return 0;
	}

	/*
	 * 检查 create_pinctrl 是否返回了其他类型的错误.
	 */
	if (IS_ERR(pctldev->p)) {
		/*
		 * 打印错误信息.
		 */
		dev_err(pctldev->dev, "error claiming hogs: %li\n",
			PTR_ERR(pctldev->p));

		/*
		 * 将错误码返回给调用者.
		 */
		return PTR_ERR(pctldev->p);
	}

	/*
	 * 查找名为 PINCTRL_STATE_DEFAULT ("default") 的状态.
	 * 这个状态定义了引脚在活动时的配置.
	 */
	pctldev->hog_default =
		pinctrl_lookup_state(pctldev->p, PINCTRL_STATE_DEFAULT);
	/*
	 * 检查查找是否失败.
	 */
	if (IS_ERR(pctldev->hog_default)) {
		dev_dbg(pctldev->dev,
			"failed to lookup the default state\n");
	} else {
		/*
		 * 如果找到了 "default" 状态, 立即调用 pinctrl_select_state 将其应用到硬件上.
		 */
		if (pinctrl_select_state(pctldev->p,
					 pctldev->hog_default))
			dev_err(pctldev->dev,
				"failed to select default state\n");
	}

	/*
	 * 查找名为 PINCTRL_STATE_SLEEP ("sleep") 的状态.
	 * 这个状态定义了引脚在系统睡眠时的配置.
	 */
	pctldev->hog_sleep =
		pinctrl_lookup_state(pctldev->p,
				     PINCTRL_STATE_SLEEP);
	/*
	 * 检查查找是否失败.
	 */
	if (IS_ERR(pctldev->hog_sleep))
		dev_dbg(pctldev->dev,
			"failed to lookup the sleep state\n");

	/*
	 * 成功处理完毕, 返回 0.
	 */
	return 0;
}
```

