# drivers/base/regmap/regmap.c
## regmap_readable - 检查寄存器是否可读
```c
bool regmap_readable(struct regmap *map, unsigned int reg)
{
	if (!map->reg_read)
		return false;

	if (map->max_register_is_set && reg > map->max_register)
		return false;

	if (map->format.format_write)
		return false;

	if (map->readable_reg)
		return map->readable_reg(map->dev, reg);

	if (map->rd_table)
		return regmap_check_range_table(map, reg, map->rd_table);

	return true;
}
```

## regmap_volatile - 检查寄存器是否是易失性的
```c
bool regmap_volatile(struct regmap *map, unsigned int reg)
{
	if (!map->format.format_write && !regmap_readable(map, reg))
		return false;

	if (map->volatile_reg)
		return map->volatile_reg(map->dev, reg);

	if (map->volatile_table)
		return regmap_check_range_table(map, reg, map->volatile_table);

	if (map->cache_ops)
		return false;
	else
		return true;
}
```

## regmap_reg_addr - 获取寄存器地址
```c
static unsigned int regmap_reg_addr(struct regmap *map, unsigned int reg)
{
	reg += map->reg_base;

	if (map->format.reg_shift > 0)
		reg >>= map->format.reg_shift;
	else if (map->format.reg_shift < 0)
		reg <<= -(map->format.reg_shift);

	return reg;
}
```

## _regmap_map_get_context - 获取寄存器映射上下文
```c
static inline void *_regmap_map_get_context(struct regmap *map)
{
	return (map->bus || (!map->bus && map->read)) ? map : map->bus_context;
}
```

## _regmap_read - 读取寄存器
```c
static int _regmap_read(struct regmap *map, unsigned int reg,
			unsigned int *val)
{
	int ret;
	void *context = _regmap_map_get_context(map);

	if (!map->cache_bypass) {
		ret = regcache_read(map, reg, val);
		if (ret == 0)
			return 0;
	}

	if (map->cache_only)
		return -EBUSY;

	if (!regmap_readable(map, reg))
		return -EIO;

	ret = map->reg_read(context, reg, val);
	if (ret == 0) {
		if (regmap_should_log(map))
			dev_info(map->dev, "%x => %x\n", reg, *val);

		trace_regmap_reg_read(map, reg, *val);

		if (!map->cache_bypass)
			regcache_write(map, reg, *val);
	}

	return ret;
}
```

## regmap_writeable - 检查寄存器是否可写
```c
bool regmap_writeable(struct regmap *map, unsigned int reg)
{
	if (map->max_register_is_set && reg > map->max_register)
		return false;

	if (map->writeable_reg)
		return map->writeable_reg(map->dev, reg);

	if (map->wr_table)
		return regmap_check_range_table(map, reg, map->wr_table);

	return true;
}
```

## _regmap_write 写入寄存器
```c
int _regmap_write(struct regmap *map, unsigned int reg,
		  unsigned int val)
{
	int ret;
	void *context = _regmap_map_get_context(map);

	if (!regmap_writeable(map, reg))
		return -EIO;

	if (!map->cache_bypass && !map->defer_caching) {
		ret = regcache_write(map, reg, val);
		if (ret != 0)
			return ret;
		if (map->cache_only) {
			map->cache_dirty = true;
			return 0;
		}
	}

	ret = map->reg_write(context, reg, val);
	if (ret == 0) {
		if (regmap_should_log(map))
			dev_info(map->dev, "%x <= %x\n", reg, val);

		trace_regmap_reg_write(map, reg, val);
	}

	return ret;
}
```

## _regmap_update_bits - 更新寄存器的特定位
```c
static int _regmap_update_bits(struct regmap *map, unsigned int reg,
			       unsigned int mask, unsigned int val,
			       bool *change, bool force_write)
{
	int ret;
	unsigned int tmp, orig;

	if (change)
		*change = false;

	if (regmap_volatile(map, reg) && map->reg_update_bits) {
		reg = regmap_reg_addr(map, reg);
		ret = map->reg_update_bits(map->bus_context, reg, mask, val);
		if (ret == 0 && change)
			*change = true;
	} else {
		ret = _regmap_read(map, reg, &orig);
		if (ret != 0)
			return ret;

		tmp = orig & ~mask;
		tmp |= val & mask;
		/* 更新寄存器的值 */
		if (force_write || (tmp != orig) || map->force_write_field) {
			ret = _regmap_write(map, reg, tmp);
			if (ret == 0 && change)
				*change = true;
		}
	}

	return ret;
}
```

## regmap_update_bits_base - 对寄存器执行读/修改/写周期
```c
/**
 * regmap_update_bits_base（） - 对寄存器执行读/修改/写周期
 *
 * @map：注册地图以进行更新
 * @reg：注册以更新
 * @mask：要更改的位掩码
 * @val：位掩码的新值
 * @change：布尔值，指示是否已完成写入
 * @async：布尔值，异步表示
 * @force：布尔值，表示使用强制更新
 *
 * 使用 change、async、force 在 register map 上执行读/修改/写周期
 *选项。
 *
 * 如果 async 为 true：
 *
 * 对于大多数总线，读取必须同步完成，因此这是最有用的
 * 对于具有缓存的设备，这些设备不需要与硬件交互
 * 确定当前寄存器值。
 *
 * 成功时返回零，出错时返回负数。
 */
int regmap_update_bits_base(struct regmap *map, unsigned int reg,
			    unsigned int mask, unsigned int val,
			    bool *change, bool async, bool force)
{
	int ret;

	map->lock(map->lock_arg);

	map->async = async;

	ret = _regmap_update_bits(map, reg, mask, val, change, force);

	map->async = false;

	map->unlock(map->lock_arg);

	return ret;
}
EXPORT_SYMBOL_GPL(regmap_update_bits_base);
```

