# fs/kernfs/dir.c
## __kernfs_new_node 创建一个新的 kernfs_node 节点
```c
static struct kernfs_node *__kernfs_new_node(struct kernfs_root *root,
					     struct kernfs_node *parent,
					     const char *name, umode_t mode,
					     kuid_t uid, kgid_t gid,
					     unsigned flags)
{
	struct kernfs_node *kn;
	u32 id_highbits;
	int ret;
   /* 分配并复制节点名称 */
	name = kstrdup_const(name, GFP_KERNEL);
	if (!name)
		return NULL;

	kn = kmem_cache_zalloc(kernfs_node_cache, GFP_KERNEL);
	if (!kn)
		goto err_out1;

	idr_preload(GFP_KERNEL);
	spin_lock(&kernfs_idr_lock);
   /* 分配一个唯一的 inode ID */
	ret = idr_alloc_cyclic(&root->ino_idr, kn, 1, 0, GFP_ATOMIC);
   /* 说明 ID 分配已经循环回到范围的起点 */
	if (ret >= 0 && ret < root->last_id_lowbits)
      /* 表示高位 ID 的生成值需要更新，以确保整体 ID 的唯一性 */
		root->id_highbits++;
	id_highbits = root->id_highbits;
   /* 更新 last_id_lowbits，记录最近分配的低位 ID */
	root->last_id_lowbits = ret;
	spin_unlock(&kernfs_idr_lock);
	idr_preload_end();
	if (ret < 0)
		goto err_out2;
   /* 使用位或操作（|）将高位生成值和低位 ID 组合成一个 64 位的唯一标识符。
      这种组合方式确保 ID 的唯一性，即使在低位 ID 范围内发生循环分配 */
	kn->id = (u64)id_highbits << 32 | ret;

	atomic_set(&kn->count, 1);
	atomic_set(&kn->active, KN_DEACTIVATED_BIAS);
   /* 红黑树节点 */
	RB_CLEAR_NODE(&kn->rb);

   /* 设置节点名称 */
	rcu_assign_pointer(kn->name, name);
	kn->mode = mode;
	kn->flags = flags;

   /* 用户或组属性与默认值不同，调用 __kernfs_setattr 设置属性 */
   /* kuid_t（用户 ID）：
   kuid_t 是内核中用于表示用户 ID 的数据类型。
   它封装了用户 ID，并支持在不同命名空间中进行映射。
   通过这种封装，内核可以确保用户 ID 在不同命名空间之间的隔离和正确转换。
   kgid_t（组 ID）：

   kgid_t 是内核中用于表示组 ID 的数据类型。
   类似于 kuid_t，它支持组 ID 在不同命名空间中的映射和隔离。
   这种设计允许内核在多用户环境中安全地管理组权限。 */
	if (!uid_eq(uid, GLOBAL_ROOT_UID) || !gid_eq(gid, GLOBAL_ROOT_GID)) {
		struct iattr iattr = {
			.ia_valid = ATTR_UID | ATTR_GID,
			.ia_uid = uid,
			.ia_gid = gid,
		};

		ret = __kernfs_setattr(kn, &iattr);
		if (ret < 0)
			goto err_out3;
	}
   /* 节点有父节点，初始化安全属性 */
	if (parent) {.
      /* return 0 */
		ret = security_kernfs_init_security(parent, kn);
		if (ret)
			goto err_out3;
	}

	return kn;

 err_out3:
	spin_lock(&kernfs_idr_lock);
	idr_remove(&root->ino_idr, (u32)kernfs_ino(kn));
	spin_unlock(&kernfs_idr_lock);
 err_out2:
	kmem_cache_free(kernfs_node_cache, kn);
 err_out1:
	kfree_const(name);
	return NULL;
}
```

## kernfs_leftmost_descendant 找到指定 kernfs_node 节点的最左后代节点
```c
static struct kernfs_node *kernfs_leftmost_descendant(struct kernfs_node *pos)
{
   /* 记录当前节点的最后访问位置 */
	struct kernfs_node *last;

	while (true) {
		struct rb_node *rbn;

		last = pos;
      /* 检查当前节点是否为目录节点（KERNFS_DIR） */
		if (kernfs_type(pos) != KERNFS_DIR)
			break;
      /* 使用 rb_first 获取红黑树中最左的子节点 */
		rbn = rb_first(&pos->dir.children);
		if (!rbn)
			break;
      /* 更新 pos 为该子节点 */
		pos = rb_to_kn(rbn);
	}

	return last;
}
```

