## copy_mnt_ns 复制挂载命名空间
```c
__latent_entropy
struct mnt_namespace *copy_mnt_ns(unsigned long flags, struct mnt_namespace *ns,
		struct user_namespace *user_ns, struct fs_struct *new_fs)
{
	struct mnt_namespace *new_ns;
	struct vfsmount *rootmnt = NULL, *pwdmnt = NULL;
	struct mount *p, *q;
	struct mount *old;
	struct mount *new;
	int copy_flags;

	BUG_ON(!ns);
	/* 未设置 CLONE_NEWNS 标志，表示新进程希望与父进程共享挂载命名空间 */
	if (likely(!(flags & CLONE_NEWNS))) {
		get_mnt_ns(ns);
		return ns;
	}

	old = ns->root;

	new_ns = alloc_mnt_ns(user_ns, false);
	if (IS_ERR(new_ns))
		return new_ns;

	namespace_lock();
	/* 初步：复制树拓扑结构 */
	copy_flags = CL_COPY_UNBINDABLE | CL_EXPIRE;
	/* 如果用户命名空间不同，设置额外的标志（CL_SHARED_TO_SLAVE）以处理挂载点的共享关系 */
	if (user_ns != ns->user_ns)
		copy_flags |= CL_SHARED_TO_SLAVE;
	new = copy_tree(old, old->mnt.mnt_root, copy_flags);
	if (IS_ERR(new)) {
		namespace_unlock();
		ns_free_inum(&new_ns->ns);
		dec_mnt_namespaces(new_ns->ucounts);
		mnt_ns_release(new_ns);
		return ERR_CAST(new);
	}
	/* 如果用户命名空间不同，更新挂载树的锁状态以确保一致性 */
	if (user_ns != ns->user_ns) {
		lock_mount_hash();
		lock_mnt_tree(new);
		unlock_mount_hash();
	}
	new_ns->root = new;

	/*
	* 第二步：切换 tsk->fs->* 元素，并将新的 vfsmounts 标记为属于新的命名空间。
	* 我们已经获取了一个私有的 fs_struct，因此不需要 tsk->fs->lock。
	*/
	p = old;
	q = new;
	/* 遍历旧挂载树和新挂载树，更新新命名空间的挂载点信息 */
	while (p) {
		mnt_add_to_ns(new_ns, q);
		new_ns->nr_mounts++;
		/* 如果提供了新的文件系统结构（new_fs），更新其根目录和当前工作目录的挂载点 */
		if (new_fs) {
			if (&p->mnt == new_fs->root.mnt) {
				new_fs->root.mnt = mntget(&q->mnt);
				rootmnt = &p->mnt;
			}
			if (&p->mnt == new_fs->pwd.mnt) {
				new_fs->pwd.mnt = mntget(&q->mnt);
				pwdmnt = &p->mnt;
			}
		}
		p = next_mnt(p, old);
		q = next_mnt(q, new);
		if (!q)
			break;
		// 我们跳过的一个mntns绑定？
		while (p->mnt.mnt_root != q->mnt.mnt_root)
			p = next_mnt(skip_mnt_tree(p), old);
	}
	namespace_unlock();

	/* 释放临时引用的挂载点资源，避免资源泄漏 */
	if (rootmnt)
		mntput(rootmnt);
	if (pwdmnt)
		mntput(pwdmnt);
	/* 将新创建的命名空间添加到命名空间树中，并返回新命名空间 */
	mnt_ns_tree_add(new_ns);
	return new_ns;
}
```

## Sysctl接口：配置挂载命名空间的最大挂载点数量

本代码片段的核心功能是向Linux内核的`sysctl`机制注册一个可配置的参数：`mount-max`。这个参数允许系统管理员在运行时通过`/proc/sys/fs/mount-max`这个虚拟文件来查看和修改单个挂载命名空间（mount namespace）中所允许的最大挂载点数量。这是一种内核参数动态调整机制，用于限制资源使用，防止潜在的滥用或错误导致系统挂载点数量失控。

### 实现原理分析

该功能完全构建在Linux的`sysctl`框架之上，该框架旨在将内核内部的变量安全地暴露给用户空间，以供查询和修改。其实现原理可分解为以下步骤：

1.  **变量定义**: 内核中定义一个全局静态变量`sysctl_mount_max`，并赋予其一个默认值（100,000）。`__read_mostly`是一个编译器优化属性，它告知编译器此变量被读取的频率远高于写入，因此应将其放置在更容易被CPU缓存的内存区域，以提升性能。
2.  **Sysctl表定义**: 创建一个`ctl_table`结构体数组`fs_namespace_sysctls`。这个表是`sysctl`接口的核心，它描述了暴露给用户空间的参数的全部属性：
    *   `.procname`: 指定在`/proc/sys/fs/`目录下创建的文件名，即`mount-max`。
    *   `.data`: 将此文件与内核变量`sysctl_mount_max`的地址进行绑定。这是实现文件读写与变量读写联动的关键。
    *   `.mode`: 定义文件的访问权限（0644，即拥有者可读写，其他用户只读）。
    *   `.proc_handler`: 指定一个处理函数`proc_dointvec_minmax`，这是一个内核提供的标准处理程序，用于读写整数值，并能进行范围检查（例如，确保设置的值不小于某个最小值）。
3.  **注册**: 定义一个初始化函数`init_fs_namespace_sysctls`，并使用`fs_initcall`宏将其注册为文件系统子系统的初始化回调。当内核启动并初始化文件系统时，此函数会被调用。
4.  **激活**: 初始化函数通过调用`register_sysctl_init("fs", ...)`，将前面定义的`fs_namespace_sysctls`表注册到`sysctl`核心中。内核会据此在`/proc/sys/`下创建`fs`目录（如果尚不存在），并在其中创建`mount-max`文件，至此该参数便对用户空间可见并可操作。

### 代码分析

```c
/* 定义一个挂载命名空间中允许的最大挂载点数量 */
// __read_mostly 是一个性能优化提示，告诉编译器这个变量大部分时间是只读的。
static unsigned int sysctl_mount_max __read_mostly = 100000;

// 仅当内核配置了CONFIG_SYSCTL时，以下代码才会被编译。
#ifdef CONFIG_SYSCTL
// 定义一个sysctl表，用于描述/proc/sys/fs/下的参数。
static const struct ctl_table fs_namespace_sysctls[] = {
	{
		// .procname: 在procfs中显示的文件名。最终路径为 /proc/sys/fs/mount-max。
		.procname	= "mount-max",
		// .data: 指向内核中实际存储该值的变量的指针。
		.data		= &sysctl_mount_max,
		// .maxlen: 变量的最大长度，此处为一个无符号整数的大小。
		.maxlen		= sizeof(unsigned int),
		// .mode: 文件权限，0644表示所有者可读写，组用户和其他用户只读。
		.mode		= 0644,
		// .proc_handler: 处理用户读写该文件的内核函数。
		// proc_dointvec_minmax 是一个标准处理整数的函数，并支持最小值/最大值检查。
		.proc_handler	= proc_dointvec_minmax,
		// .extra1: 传递给proc_handler的额外参数。SYSCTL_ONE通常表示允许的最小值为1。
		.extra1		= SYSCTL_ONE,
	},
};

// init_fs_namespace_sysctls: 初始化函数，用于注册上述sysctl表。
// __init 标记表示该函数仅在内核初始化期间使用，之后其占用的内存可以被回收。
static int __init init_fs_namespace_sysctls(void)
{
	// 调用内核函数，将fs_namespace_sysctls表注册到/proc/sys/fs/目录下。
	register_sysctl_init("fs", fs_namespace_sysctls);
	return 0;
}
// fs_initcall: 一个宏，用于将init_fs_namespace_sysctls函数注册为文件系统初始化阶段的回调。
// 这确保了在procfs准备好之后再进行注册。
fs_initcall(init_fs_namespace_sysctls);

#endif /* CONFIG_SYSCTL */
```

## VFS写访问控制：确保文件系统状态变更的安全性

本代码片段是Linux VFS层中负责管理对文件系统写操作权限的核心机制。它的主要功能不是简单地检查文件系统是否为只读，而是实现一个复杂而健壮的同步协议。这个协议确保了当一个任务（例如，用户执行`remount,ro`命令或`fsfreeze`）试图将文件系统变为只读或“冻结”状态时，不会与正在进行或即将开始的写操作（如`write()`, `unlink()`）发生竞争，从而避免数据损坏。可以把它想象成是文件系统写操作的“空中交通管制”，在改变“跑道”（文件系统状态）之前，必须确保所有“飞机”（写操作）都已安全落地或暂停起飞。

### 实现原理分析

这个机制的核心思想是一个多阶段的“握手”协议，它使用原子计数器、特殊标志位和内存屏障来协调两类活动：
1.  **写者（Writers）**: 任何想要向文件系统写入数据的内核路径（例如，处理`write()`系统调用）。
2.  **状态改变者（State Changers）**: 想要将文件系统变为只读或冻结状态的内核路径（例如，处理`mount(MS_REMOUNT | MS_RDONLY)`）。

这个握手协议的流程如下：

**对于一个“写者” (`mnt_want_write`)**:

1.  **第一道门：冻结保护 (`sb_start_write`)**: 写者首先通知超级块（superblock），它想要开始写操作。如果文件系统当前处于“冻结”（frozen）状态，`sb_start_write`将会阻塞，直到文件系统被“解冻”。这是第一层保护。
2.  **第二道门：只读挂载保护 (`mnt_get_write_access`)**: 这是更复杂的一步。
    a. **宣告意图**: 写者首先原子地增加一个“写者计数器”（`mnt_inc_writers`）。这就像是举手说：“我正准备开始写！”。
    b. **检查“暂停”标志**: 写者接着检查一个名为`MNT_WRITE_HOLD`的标志。当一个“状态改变者”想要将文件系统变为只读时，它会先设置这个标志，意为：“所有新的写者请在此暂停！”。如果写者看到这个标志被设置，它就会在一个循环中等待，直到标志被清除。
    c. **最终确认**: 当`MNT_WRITE_HOLD`标志被清除后（意味着状态改变已经完成），写者并不会立即开始写。它会最后再调用一次`mnt_is_readonly`来检查文件系统**现在**是否已经是只读的。因为可能就在它等待的期间，文件系统已经成功地被设置为只读了。
    d. **成功或放弃**: 如果此时文件系统是只读的，写者就必须放弃，它会递减之前增加的写者计数器，并返回`-EROFS`错误。如果不是只读的，它就成功获得了写权限，函数返回0，写操作可以继续。
3.  **完成写入**: 写操作完成后，写者必须调用`mnt_drop_write`（或其底层函数`mnt_put_write_access`和`sb_end_write`），它们会递减写者计数器和超级块的写计数。

**内存屏障 (`smp_mb`, `smp_rmb`) 的关键作用**:

在多核处理器上，一个CPU对内存的写入操作不会立即对所有其他CPU可见。内存屏障就是用来强制实施一个“可见性”顺序的指令。
*   `smp_mb()` (写者端): 保证“我增加了写者计数器”这个事实，**必须**在“我检查`MNT_WRITE_HOLD`标志”这个动作**之前**，被所有其他CPU看到。这防止了状态改变者错误地认为没有写者而继续操作。
*   `smp_rmb()` (写者端): 保证“我看到了`MNT_WRITE_HOLD`标志已被清除”这个事实之后，我才能去读取最终的只读标志。这确保了我看到的是状态改变完成**之后**的最终结果。

### 代码分析

#### `mnt_is_readonly` 函数
这是一个经过精心设计的只读状态检查函数，它不仅仅是读取一个标志。

```c
static int mnt_is_readonly(struct vfsmount *mnt)
{
	// 步骤1: 快速检查。s_readonly_remount是remount过程开始时设置的标志。
	// READ_ONCE确保我们从内存真实地读取该值，而不是使用寄存器中可能过时的值。
	if (READ_ONCE(mnt->mnt_sb->s_readonly_remount))
		return 1; // 如果remount正在进行中，就直接认为它是只读的。

	/*
	 * 步骤2: 内存屏障。这是为了解决竞争条件的关键。
	 * 它确保了：如果我们在上面没有看到s_readonly_remount被设置，那么我们也
	 * 不会看到remount操作稍后对MNT_READONLY等标志的修改。
	 * 这就强制了一个“观察顺序”，防止我们看到一个不一致的、半完成的状态。
	 */
	smp_rmb();

	// 步骤3: 调用内部函数，检查最终的只读标志(MNT_READONLY和SB_RDONLY)。
	return __mnt_is_readonly(mnt);
}
```

#### `mnt_get_write_access` 函数
这是专门处理与`remount,ro`竞争的核心函数。

```c
int mnt_get_write_access(struct vfsmount *m)
{
	struct mount *mnt = real_mount(m); // 获取内部的mount结构体。
	int ret = 0;

	preempt_disable(); // 禁用内核抢占，进入一个微小的临界区。
	mnt_inc_writers(mnt); // 原子地增加写者计数，宣告“我打算写”。

	/*
	 * 步骤A: 全功能内存屏障。
	 * 确保上面对写者计数的增加，对所有其他CPU都是可见的，
	 * 然后我们才能继续去检查MNT_WRITE_HOLD标志。
	 */
	smp_mb();

	might_lock(&mount_lock.lock); // 调试辅助，告诉锁检查器我们可能会获取这个锁。

	// 步骤B: 等待循环。如果remount操作设置了MNT_WRITE_HOLD，就在此等待。
	while (READ_ONCE(mnt->mnt.mnt_flags) & MNT_WRITE_HOLD) {
		if (!IS_ENABLED(CONFIG_PREEMPT_RT)) {
			cpu_relax(); // 在非实时内核中，只是一个CPU提示，表示在忙等。
		} else {
			// 在实时内核中，这是一个更复杂的机制，用于防止优先级反转。
			// 它会短暂地重新启用抢占，尝试获取并释放一个全局锁来主动让出CPU。
			/* 我们并不需要这个锁来保护任何数据，我们的目的只是为了“排队”。所以，我们立即调用unlock_mount_hash()将其释放，以免阻塞其他真正需要这个锁的任务。 */
			preempt_enable();
			lock_mount_hash();
			unlock_mount_hash();
			preempt_disable();
		}
	}

	/*
	 * 步骤C: 读内存屏障。
	 * 确保：既然我们已经看到MNT_WRITE_HOLD被清除了，那么我们也一定能看到
	 * remount操作对s_readonly_remount或最终只读标志的修改。
	 * 这关闭了竞争的窗口。
	 */
	smp_rmb();

	// 步骤D: 最终检查。在所有的同步和等待之后，最后再确认一次文件系统是否真的只读。
	if (mnt_is_readonly(m)) {
		mnt_dec_writers(mnt); // 如果是只读，就撤销之前的写意图。
		ret = -EROFS;         // 设置返回值为“只读文件系统”。
	}
	preempt_enable(); // 退出临界区，允许内核抢占。

	return ret;
}
EXPORT_SYMBOL_GPL(mnt_get_write_access);
```

#### `mnt_want_write` 函数
这是提供给内核大部分代码使用的顶层API，它同时处理“冻结”和“只读”两种状态。

```c
int mnt_want_write(struct vfsmount *m)
{
	int ret;

	// 第一道关卡：处理文件系统冻结（freeze）。
	// 如果文件系统被冻结，这个函数会等待直到解冻。
	sb_start_write(m->mnt_sb);

	// 第二道关卡：处理只读挂载（remount,ro）。
	ret = mnt_get_write_access(m);

	// 如果第二道关卡失败了（返回错误），我们必须撤销第一道关卡的操作。
	if (ret)
		sb_end_write(m->mnt_sb);

	return ret;
}
EXPORT_SYMBOL_GPL(mnt_want_write);
```

