## cpuhp_setup_state_nocalls 设置 CPU 热插拔状态
```c
/**
 * __cpuhp_setup_state_cpuslocked - 设置热插拔计算机状态的回调
 * @state：要设置的状态
 * @name：步骤名称
 * @invoke：如果为 true，则为其中
 * CPU 状态 >= @state
 * @startup：启动回调函数
 * @teardown：teardown 回调函数
 * @multi_instance：为多个实例设置状态，这些实例获取
 * 后添加。
 *
 * 调用者在调用此函数时需要保持 cpus 读锁定。
 *返回：
 * 成功时：
 * 如果 @state 为 CPUHP_AP_ONLINE_DYN 或 CPUHP_BP_PREPARE_DYN，则为正数状态号;
 * 0 表示所有其他状态
 * 失败时：正确（负）错误代码
 */
int __cpuhp_setup_state_cpuslocked(enum cpuhp_state state,
				   const char *name, bool invoke,
				   int (*startup)(unsigned int cpu),
				   int (*teardown)(unsigned int cpu),
				   bool multi_instance)
{
	int cpu, ret = 0;
	bool dynstate;

	lockdep_assert_cpus_held();

	if (cpuhp_cb_check(state) || !name)
		return -EINVAL;

	mutex_lock(&cpuhp_state_mutex);

	ret = cpuhp_store_callbacks(state, name, startup, teardown,
				    multi_instance);

	dynstate = state == CPUHP_AP_ONLINE_DYN || state == CPUHP_BP_PREPARE_DYN;
	if (ret > 0 && dynstate) {
		state = ret;
		ret = 0;
	}

	if (ret || !invoke || !startup)
		goto out;

	/*
	 * Try to call the startup callback for each present cpu
	 * depending on the hotplug state of the cpu.
	 */
	for_each_present_cpu(cpu) {
		struct cpuhp_cpu_state *st = per_cpu_ptr(&cpuhp_state, cpu);
		int cpustate = st->state;

		if (cpustate < state)
			continue;

		ret = cpuhp_issue_call(cpu, state, true, NULL);
		if (ret) {
			if (teardown)
				cpuhp_rollback_install(cpu, state, NULL);
			cpuhp_store_callbacks(state, NULL, NULL, NULL, false);
			goto out;
		}
	}
out:
	mutex_unlock(&cpuhp_state_mutex);
	/*
	 * If the requested state is CPUHP_AP_ONLINE_DYN or CPUHP_BP_PREPARE_DYN,
	 * return the dynamically allocated state in case of success.
	 */
	if (!ret && dynstate)
		return state;
	return ret;
}

/**
 * cpuhp_setup_state_nocalls - 设置热插拔状态回调，而不调用
 * @startup 回调
 * @state：呼叫的安装状态
 * @name：回调的名称。
 * @startup：启动回调函数或 NULL（如果不需要）
 * @teardown：teardown 回调函数或 NULL（如果不需要）
 *
 * 与 cpuhp_setup_state（） 相同，只是在安装过程中不调用 @startup 回调。如果 SMP=n 或 HOTPLUG_CPU=n，则为 NOP。
 */
static inline int cpuhp_setup_state_nocalls(enum cpuhp_state state,
					    const char *name,
					    int (*startup)(unsigned int cpu),
					    int (*teardown)(unsigned int cpu))
{
	return __cpuhp_setup_state(state, name, false, startup, teardown,
				   false);
}
```


# kernel/smpboot.c
## __smpboot_create_thread 创建一个内核线程
- 根据一个给定的线程模板（struct smp_hotplug_thread *ht），在一个指定的CPU（unsigned int cpu）上，实际地创建一个、绑定并准备好一个内核线程。
```c
/*
 * 这是一个静态的内部函数，用于在一个指定的CPU上，根据一个热插拔线程模板来创建线程。
 * @ht:  指向smp_hotplug_thread线程模板的指针。
 * @cpu: 目标CPU的编号。
 *
 * 返回值: 0表示成功，负的错误码表示失败。
 */
static int
__smpboot_create_thread(struct smp_hotplug_thread *ht, unsigned int cpu)
{
	/* tsk: 指向新创建任务的task_struct的指针。*/
	struct task_struct *tsk = *per_cpu_ptr(ht->store, cpu);
	/* td: 指向一个临时的数据结构，用于向新线程传递参数。*/
	struct smpboot_thread_data *td;

	/*
	 * 检查ht->store这个per-cpu数组中，对应于当前cpu的槽位是否已经有值。
	 * per_cpu_ptr(ht->store, cpu)获取该槽位的地址，'*'解引用获取其内容。
	 */
	if (tsk)
		/* 如果已经存在，说明线程已创建，直接返回成功。*/
		return 0;

	/*
	 * 为smpboot_thread_data动态分配内存。
	 * GFP_KERNEL表示这是一个常规的、可能引起睡眠的内核内存分配。
	 * cpu_to_node(cpu)确保内存在与目标CPU亲和的NUMA节点上分配。
	 */
	td = kzalloc_node(sizeof(*td), GFP_KERNEL, cpu_to_node(cpu));
	/* 如果内存分配失败，返回-ENOMEM错误。*/
	if (!td)
		return -ENOMEM;
	/* 将目标CPU编号和线程模板指针存入td中，以便传递。*/
	td->cpu = cpu;
	td->ht = ht;

	/*
	 * 调用kthread_create_on_cpu()来创建并绑定线程。
	 * - smpboot_thread_fn: 是所有通过此框架创建的线程的通用入口函数。
	 * - td:                是传递给smpboot_thread_fn的参数。
	 * - cpu:                 指定线程必须在这个CPU上创建和运行。
	 * - ht->thread_comm:     是线程名的格式化字符串，如"ksoftirqd/%u"。
	 */
	tsk = kthread_create_on_cpu(smpboot_thread_fn, td, cpu,
				    ht->thread_comm);
	/* 检查kthread_create_on_cpu是否返回了一个错误。IS_ERR会判断指针是否编码了错误。*/
	if (IS_ERR(tsk)) {
		/* 如果创建失败，释放之前分配的td内存。*/
		kfree(td);
		/* 使用PTR_ERR从指针中提取出负的错误码并返回。*/
		return PTR_ERR(tsk);
	}
	/* 调用kthread_set_per_cpu，在task_struct中设置这是一个per-cpu线程的标志。*/
	kthread_set_per_cpu(tsk, cpu);
	/*
	 * 注释：停泊该线程，以便当CPU可用时，它能立刻在该CPU上启动。
	 */
	/* 调用kthread_park，向新线程发出一个“请停泊”的请求。*/
	kthread_park(tsk);
	/*
	 * 增加新线程tsk的引用计数。因为我们将要把它的指针存入一个全局的
	 * per-cpu变量中，必须增加引用计数以防止它意外消失。
	 */
	get_task_struct(tsk);
	/* 将新创建的task_struct指针，存入ht->store的对应CPU槽位中。*/
	*per_cpu_ptr(ht->store, cpu) = tsk;

	/* 检查线程模板中是否提供了一个create回调函数。*/
	if (ht->create) {
		/*
		 * 注释：在调用create回调之前，确保该任务实际上已经调度出去并
		 *       进入了停泊位置。至少，迁移线程的回调要求任务已不在运行队列上。
		 */
		/*
		 * 调用wait_task_inactive，同步等待，直到tsk的状态变为TASK_PARKED。
		 * 如果等待失败，则触发一个内核警告。
		 */
		if (!wait_task_inactive(tsk, TASK_PARKED))
			WARN_ON(1);
		else
			/* 在确认线程已停泊后，安全地调用用户提供的create回调函数。*/
			ht->create(cpu);
	}
	/* 返回0表示成功。*/
	return 0;
}
```

## smpboot_destroy_threads 销毁所有与热插拔相关的线程
```c
static void smpboot_destroy_threads(struct smp_hotplug_thread *ht)
{
	unsigned int cpu;

	/* We need to destroy also the parked threads of offline cpus */
	for_each_possible_cpu(cpu) {
		struct task_struct *tsk = *per_cpu_ptr(ht->store, cpu);

		if (tsk) {
			kthread_stop_put(tsk);
			*per_cpu_ptr(ht->store, cpu) = NULL;
		}
	}
}
```

## smpboot_unpark_thread 唤醒一个停泊的线程
```c
static void smpboot_unpark_thread(struct smp_hotplug_thread *ht, unsigned int cpu)
{
	struct task_struct *tsk = *per_cpu_ptr(ht->store, cpu);

	if (!ht->selfparking)
		kthread_unpark(tsk);
}
```

## smpboot_register_percpu_thread 注册一个与热插拔相关的per_cpu线程
```c
static LIST_HEAD(hotplug_threads);
static DEFINE_MUTEX(smpboot_threads_lock);

/**
 * smpboot_register_percpu_thread - 注册一个与热插拔相关的per_cpu线程
 * @plug_thread:	热插拔线程的描述符结构体指针。
 *
 * 在所有在线的CPU上创建并启动这些线程。
 */
int smpboot_register_percpu_thread(struct smp_hotplug_thread *plug_thread)
{
	/* cpu: 用于在循环中迭代CPU编号。*/
	unsigned int cpu;
	/* ret: 用于存储函数返回值，默认为0(成功)。*/
	int ret = 0;

	/*
	 * 获取cpus_read_lock读锁，以创建一个稳定的CPU视图，防止在遍历期间
	 * CPU的在线状态发生改变。
	 */
	cpus_read_lock();
	/*
	 * 获取smpboot_threads_lock互斥锁，以保护对全局hotplug_threads链表的
	 * 并发访问。
	 */
	mutex_lock(&smpboot_threads_lock);

	/* 使用for_each_online_cpu宏，遍历系统中所有当前处于“在线”状态的CPU。*/
	for_each_online_cpu(cpu) {
		/*
		 * 调用内部辅助函数__smpboot_create_thread，根据plug_thread模板，
		 * 为指定的cpu创建一个内核线程。
		 */
		ret = __smpboot_create_thread(plug_thread, cpu);
		/* 如果线程创建失败（ret不为0）。*/
		if (ret) {
			/* 调用smpboot_destroy_threads，清理掉所有已经为这个
			 * plug_thread模板创建成功的线程，以回滚操作。*/
			smpboot_destroy_threads(plug_thread);
			/* 跳转到out标签，准备解锁并返回错误。*/
			goto out;
		}
		/* 如果创建成功，则调用smpboot_unpark_thread唤醒这个新创建的、
		 * 处于停泊状态的线程，让它开始运行。*/
		smpboot_unpark_thread(plug_thread, cpu);
	}
	/*
	 * 在为所有当前在线的CPU都创建了线程之后，将这个plug_thread模板
	 * 添加到全局的hotplug_threads链表中。
	 * 这确保了未来有新CPU上线时，也会为它创建这个线程。
	 */
	list_add(&plug_thread->list, &hotplug_threads);
out:
	/* 释放互斥锁。*/
	mutex_unlock(&smpboot_threads_lock);
	/* 释放读锁。*/
	cpus_read_unlock();
	/* 返回操作结果（0表示成功，否则为错误码）。*/
	return ret;
}
/*
 * 将smpboot_register_percpu_thread函数符号以GPL兼容的方式导出，
 * 使得遵循GPL许可的可加载内核模块也能调用它。
 */
EXPORT_SYMBOL_GPL(smpboot_register_percpu_thread);
```

## smpboot_thread_fn - per-cpu热插拔线程的循环函数
```c
/**
 * smpboot_thread_fn - per-cpu热插拔线程的循环函数
 * @data:	线程的数据指针
 *
 * 检查线程的停止和停泊条件。为已注册的线程调用必要的
 * setup, cleanup, park和unpark函数。
 *
 * 返回值: 当线程应该退出时返回1，否则返回0。
 * (注：根据实现，它最终返回0来退出)
 */
static int smpboot_thread_fn(void *data)
{
	/* td: 指向本次线程实例的私有数据，包含了cpu编号和ht模板指针。*/
	struct smpboot_thread_data *td = data;
	/* ht: 指向定义了这类per-cpu线程通用行为的模板结构体。*/
	struct smp_hotplug_thread *ht = td->ht;

	/* 进入无限循环，构成线程的主体。*/
	while (1) {
		/* 将自己的状态置为可中断睡眠，准备在无事可做时睡眠。*/
		set_current_state(TASK_INTERRUPTIBLE);
		/* 在检查状态前禁用抢占，以防止在检查和睡眠之间产生竞争。*/
		preempt_disable();
		/* 检查是否有外部请求要求本线程停止并退出。*/
		if (kthread_should_stop()) {
			/* 如果需要停止，则恢复为运行状态以执行清理。*/
			__set_current_state(TASK_RUNNING);
			/* 重新使能抢占。*/
			preempt_enable();
			/* 清理必须与设置镜像对应。*/
			/* 如果模板中定义了cleanup回调，并且本线程已初始化过，则调用它。*/
			if (ht->cleanup && td->status != HP_THREAD_NONE)
				ht->cleanup(td->cpu, cpu_online(td->cpu));
			/* 释放为本次实例分配的私有数据td。*/
			kfree(td);
			/* 从线程主函数返回0，这将最终导致kthread_exit被调用。*/
			return 0;
		}

		/* 检查是否有外部请求要求本线程暂停工作并进入停泊状态。*/
		if (kthread_should_park()) {
			/* 恢复运行状态以执行停泊前的回调。*/
			__set_current_state(TASK_RUNNING);
			preempt_enable();
			/* 如果模板中定义了park回调，并且线程当前是活跃的。*/
			if (ht->park && td->status == HP_THREAD_ACTIVE) {
				/* 健壮性检查：确保我们在预期的CPU上运行。*/
				BUG_ON(td->cpu != smp_processor_id());
				/* 调用park回调。*/
				ht->park(td->cpu);
				/* 更新内部状态为已停泊。*/
				td->status = HP_THREAD_PARKED;
			}
			/* 调用kthread框架的标准停泊函数，它会让自己睡眠。*/
			kthread_parkme();
			/* 我们可能因为stop而被唤醒。*/
			/* 当从kthread_parkme()唤醒后，继续下一次主循环，重新评估所有状态。*/
			continue;
		}

		/* 健壮性检查：再次确认我们运行在正确的CPU上。*/
		BUG_ON(td->cpu != smp_processor_id());

		/* 检查状态机，以执行一次性的setup或unpark操作。*/
		switch (td->status) {
		case HP_THREAD_NONE: /* 初始状态，线程首次运行。*/
			__set_current_state(TASK_RUNNING);
			preempt_enable();
			/* 如果模板中定义了setup回调，则调用它。*/
			if (ht->setup)
				ht->setup(td->cpu);
			/* 将状态迁移到活跃状态。*/
			td->status = HP_THREAD_ACTIVE;
			/* 继续下一次主循环。*/
			continue;

		case HP_THREAD_PARKED: /* 从停泊状态被唤醒。*/
			__set_current_state(TASK_RUNNING);
			preempt_enable();
			/* 如果模板中定义了unpark回调，则调用它。*/
			if (ht->unpark)
				ht->unpark(td->cpu);
			/* 将状态迁移到活跃状态。*/
			td->status = HP_THREAD_ACTIVE;
			/* 继续下一次主循环。*/
			continue;
		}

		/* 如果模板中定义了thread_should_run回调，则调用它判断当前是否真的有工作要做。*/
		if (!ht->thread_should_run(td->cpu)) {
			/* 如果没有工作，则使能抢占（但不检查重新调度），然后调用schedule()主动让出CPU。*/
			preempt_enable_no_resched();
			schedule();
		} else {
			/* 如果有工作要做，则恢复运行状态并使能抢占。*/
			__set_current_state(TASK_RUNNING);
			preempt_enable();
			/* 调用模板中定义的核心工作函数。*/
			ht->thread_fn(td->cpu);
		}
	}
}
```

# kernel/sched/completion.c 内核同步原语(Kernel Synchronization Primitive) 简洁的任务完成信号量

### 历史与背景
#### 这项技术是为了解决什么特定问题而诞生的？
这项技术以及它所实现的“完成量”（Completion），是为了提供一个**高度简化的、专门用于解决“一个执行单元等待另一个执行单元完成某项工作”这一特定同步场景**的内核原语。
*   **简化样板代码**：在`completion`出现之前，要实现这种“等待-通知”的模式，开发者必须手动组合更底层的原语。这通常意味着：
    1.  定义一个`wait_queue_head_t`（等待队列头）。
    2.  定义一个`bool`或`int`类型的标志位来表示任务是否完成。
    3.  等待者需要在一个循环中调用`wait_event_interruptible()`，这个宏会自动处理将任务加入等待队列、睡眠、被唤醒后检查标志位、处理伪唤醒等一系列复杂操作。
    4.  完成者需要设置标志位，然后调用`wake_up()`来唤醒等待者。
    这个过程虽然强大，但对于一个非常常见的模式来说，显得过于繁琐且容易出错（例如，忘记处理竞态条件）。
*   **解决竞态条件**：一个经典的竞态条件是“完成发生在等待之前”（Completion-before-wait）。如果任务在等待者调用`wait_event`之前就已经完成并发出信号，那么这个信号就会丢失，导致等待者永久睡眠。`completion`机制从设计上就完美地解决了这个问题。

`completion`的诞生，就是为了将上述所有复杂性封装成一个极其简单、健壮且易于使用的API，让开发者可以专注于业务逻辑，而不是同步细节。

#### 它的发展经历了哪些重要的里程碑或版本迭代？
`completion`作为一个基础的同步原语，其核心API非常稳定，其发展主要体现在内部实现的优化上。
*   **引入**：`completion`被引入内核，提供了`init_completion`, `wait_for_completion`, `complete`这三个核心API，极大地简化了内核中的同步代码。
*   **性能优化**：`completion`内部实现的一个关键优化是针对“完成发生在等待之前”的快速路径。它内部有一个`done`计数器。当`wait_for_completion`被调用时，它会首先检查这个计数器。如果计数器大于0，意味着任务已经完成，等待者根本无需睡眠，可以直接递减计数器并立即返回。这避免了进入调度器、上下文切换等昂贵的操作。
*   **API扩展**：为了支持更广泛的场景，后续加入了`complete_all()`（唤醒所有等待者，而不仅仅是一个）、`reinit_completion()`（允许一个completion对象被重用）以及各种可中断、可超时的等待变体（如`wait_for_completion_timeout`, `wait_for_completion_interruptible`）。

#### 目前该技术的社区活跃度和主流应用情况如何？
`completion`是内核中最基础、最稳定、使用最广泛的同步原语之一。
*   **社区活跃度**：其代码库和API极其稳定，处于纯维护状态。它被认为是内核同步工具箱中一个“已解决的问题”。
*   **主流应用**：它的应用遍布内核的每一个角落。
    *   **驱动程序**：一个驱动向硬件发送一个命令后，可以调用`wait_for_completion`来睡眠，直到硬件完成操作并通过中断处理程序调用`complete`。
    *   **内核线程同步**：一个内核线程在启动后，可以调用`complete`来通知其创建者自己已经完成初始化。反之，在线程退出时，也可以用它来等待所有子任务完成。
    *   **核心内核**：`vfork()`系统调用的实现就用到了`completion`，父进程用它来等待子进程执行`exec()`或`exit()`。

### 核心原理与设计
#### 它的核心工作原理是什么？
`completion`的实现巧妙地封装了`wait_queue_head_t`，并增加了一个状态计数器来解决竞态问题。
`struct completion`结构体主要包含两个成员：
*   `unsigned int done;`：一个计数器，表示“完成”事件发生的次数。
*   `wait_queue_head_t wait;`：一个标准的等待队列头，用于让任务在此睡眠。

**工作流程**：
1.  **初始化 (`init_completion`)**：将`done`计数器清零，并初始化等待队列头。

2.  **等待 (`wait_for_completion`)**：
    *   **快速路径**：检查`done`计数器。如果`done > 0`，说明`complete()`已经被调用过了。此时，函数会原子地将`done`减1，然后**立即返回**，根本不会睡眠。
    *   **慢速路径**：如果`done == 0`，说明任务尚未完成。函数会将当前任务加入到`wait`队列中，并调用调度器使其进入睡眠状态。

3.  **完成 (`complete`)**：
    *   原子地将`done`计数器加1。
    *   检查等待队列`wait`是否为空。如果不为空，就调用`wake_up()`唤醒**一个**正在睡眠的任务。

这个设计的精妙之处在于`done`计数器。它使得`wait`和`complete`的调用顺序无关紧要。
*   如果`wait`先调用，任务会睡眠，等待`complete`来唤醒它。
*   如果`complete`先调用，`done`会变为1，之后`wait`被调用时会看到`done > 0`，直接从快速路径返回。信号绝不会丢失。

#### 它的主要优势体现在哪些方面？
*   **API极其简洁**：完美地抽象了“等待-通知”模型，隐藏了所有底层复杂性。
*   **健壮**：从设计上就避免了“完成先于等待”的竞态条件。
*   **高效**：为“完成先于等待”的常见场景提供了无上下文切换的快速路径。

#### 它存在哪些已知的劣势、局-限性或在特定场景下的不适用性？
*   **功能专一**：它是一个高度特化的工具，只适用于“任务完成”这种一次性的、单向的信令。
*   **不用于互斥**：它**绝对不能**被用来保护临界区或共享数据。这是互斥锁（mutex）或自旋锁（spinlock）的工作。
*   **不用于资源计数**：它不适合用来管理对一组资源的访问。这是信号量（semaphore）的工作。

### 使用场景
#### 在哪些具体的业务或技术场景下，它是首选解决方案？
当一个执行流需要**阻塞**自己，直到另一个执行流（或中断上下文）显式地通知它某个**一次性事件**已经发生时，`completion`是**简单、安全且首选的**解决方案。
*   **模块卸载**：当一个模块被卸载时，它可能需要等待所有正在使用其资源的内核线程都安全退出。卸载代码可以为每个线程调用`wait_for_completion`，而每个线程在退出前调用`complete`。
*   **同步I/O操作**：一个块设备驱动在处理一个同步的`read`请求时，会将请求加入硬件的命令队列，然后`wait_for_completion`。当硬件完成读取并通过中断通知驱动时，中断处理程序会调用`complete`，唤醒等待的进程，使其可以拷贝数据并返回给用户。

#### 是否有不推荐使用该技术的场景？为什么？
*   **保护共享数据**：当多个线程需要互斥地访问一个共享变量时，应该使用`mutex_lock`/`mutex_unlock`。`completion`无法提供互斥保证。
*   **有条件的等待**：当一个线程需要等待一个复杂的条件变为真（例如，等待一个队列既不为空也不为满）时，应该使用底层的`wait_event()`宏，因为它天生就是与条件判断结合在一起的。
*   **生产者-消费者队列**：虽然可以用`completion`来实现简单的生产者-消费者信令，但信号量（`ksem`）通常是更通用、更合适的工具，因为它能自然地处理队列中的多个“槽位”。

### 对比分析
#### 请将其 与 其他相似技术 进行详细对比。

| 特性 | Completion (完成量) | Mutex (互斥锁) | Semaphore (信号量) | Wait Queue (等待队列) |
| :--- | :--- | :--- | :--- | :--- |
| **主要目的** | **信令/同步 (Signaling)**。表示一个任务已完成。 | **互斥 (Mutual Exclusion)**。保护临界区，保证只有一个执行者能进入。 | **资源计数 (Resource Counting)**。控制对N个资源的并发访问。 | **底层等待机制 (Waiting Mechanism)**。让任务在某个条件上睡眠。 |
| **核心操作** | `wait_for_completion`, `complete` | `mutex_lock`, `mutex_unlock` | `down`, `up` | `wait_event`, `wake_up` |
| **解决的问题** | “等待工作完成” | “保护这段代码不被并发执行” | “最多只允许N个线程通过” | “当这个条件不满足时，就睡吧” |
| **抽象层级** | **高层**。是对Wait Queue的封装。 | **高层**。 | **高层**。 | **底层**。是其他同步原语的基础。 |
| **是否可重入** | `complete`可以被多次调用，`done`计数器会累加。 | 不可重入（常规mutex）。 | 可重入（多次`up`会增加计数值）。 | N/A |
| **竞态处理** | **内置**。完美处理“完成先于等待”的竞态。 | N/A (用于解决竞态) | 需要小心使用以避免竞态。 | **需要手动处理**。必须与一个条件变量和正确的锁配合使用。 |

# include/linux/completion.h
## init_completion 初始化完成量
```c
/**
 * init_completion - 初始化动态分配的完成
 * @x：指向要初始化的完成结构的指针
 *
 * 此内联函数将初始化动态创建的完成结构。
 */
static inline void init_completion(struct completion *x)
{
	x->done = 0;
	init_swait_queue_head(&x->wait); // 初始化等待队列头
}
```

## DECLARE_COMPLETION_ONSTACK 声明完成量
```c
