# kernel/sched/completion.c
## wait_for_common  等待完成量
```c
static inline long __sched
do_wait_for_common(struct completion *x,
		   long (*action)(long), long timeout, int state)
{
   	/*  x->done 为 0，表示条件尚未完成，需要进入等待逻辑 */
	if (!x->done) {
      /* 使用 DECLARE_SWAITQUEUE(wait) 声明一个等待队列条目 wait，用于将当前线程加入到 x->wait 的等待队列中 */
		DECLARE_SWAITQUEUE(wait);

		do {
         /* 检查当前线程是否有挂起的信号 */
			if (signal_pending_state(state, current)) {
				timeout = -ERESTARTSYS;
				break;
			}
         /* 将当前线程添加到 x->wait 的等待队列中，并设置线程的状态为 state */
			__prepare_to_swait(&x->wait, &wait);
			__set_current_state(state);

			raw_spin_unlock_irq(&x->wait.lock);
         	/* 执行传入的回调函数（通常是一个等待操作，如 schedule_timeout），进入睡眠并更新超时时间 */
			timeout = action(timeout);
			raw_spin_lock_irq(&x->wait.lock);
		} while (!x->done && timeout);
      	/* 调用 __finish_swait 将当前线程从等待队列中移除 */
		__finish_swait(&x->wait, &wait);
		if (!x->done)
			return timeout;
	}
   /* 如果 x->done 不等于 UINT_MAX（表示条件未被永久完成），则将其递减，表示一个等待线程已完成 
   有多个线程在等待同一个完成事件，x->done 的值可以大于 1，表示该事件可以唤醒多个线程。
   每当一个线程被唤醒并处理完成事件时，x->done 会递减，直到其值为 0，表示事件已被完全消耗。*/
	if (x->done != UINT_MAX)
		x->done--;
	return timeout ?: 1;
}

static inline long __sched
__wait_for_common(struct completion *x,
		  long (*action)(long), long timeout, int state)
{
	might_sleep();

	complete_acquire(x);

	raw_spin_lock_irq(&x->wait.lock);
	timeout = do_wait_for_common(x, action, timeout, state);
	raw_spin_unlock_irq(&x->wait.lock);

	complete_release(x);

	return timeout;
}

static long __sched
wait_for_common(struct completion *x, long timeout, int state)
{
	return __wait_for_common(x, schedule_timeout, timeout, state);
}
```

## wait_for_completion 等待完成量 state TASK_UNINTERRUPTIBLE 不可被中断
```c
/**
 * 等待完成: - 等待任务的完成 * 
 * @x: 保存此特定完成的状态 * 
 * 这将等待特定任务完成的信号。它不可被打断，并且没有超时。 * 
 * 另见类似例程（即 wait_for_completion_timeout()），它具有超时和可中断能力。另见 complete()。
 */
void __sched wait_for_completion(struct completion *x)
{
	wait_for_common(x, MAX_SCHEDULE_TIMEOUT, TASK_UNINTERRUPTIBLE);
}
EXPORT_SYMBOL(wait_for_completion);

```

## wait_for_completion_killable 等待完成量
```c
/* wait_for_completion_killable: - 等待一个任务的完成（可被杀死） 
 * @x: 保存此特定完成的状态 * * 这会等待特定任务完成的信号。可以被杀死信号中断。 * 
 * 返回：-ERESTARTSYS 如果被中断，0 如果已完成。 
*/
int __sched wait_for_completion_killable(struct completion *x)
{
   /* #define TASK_KILLABLE			(TASK_WAKEKILL | TASK_UNINTERRUPTIBLE) */
	long t = wait_for_common(x, MAX_SCHEDULE_TIMEOUT, TASK_KILLABLE);

	if (t == -ERESTARTSYS)
		return t;
	return 0;
}
EXPORT_SYMBOL(wait_for_completion_killable);
```

## complete_with_flags 完成量完成 
```c
/* * 通用等待完成的处理程序； *
 * 它与信号量不同，信号量的默认情况相反，wait_for_completion默认是阻塞的，而信号量默认是非阻塞的。这个接口还使得‘完成’多个等待线程变得简单，这对于信号量并不是完全自然的。 *
 * 但更重要的是，这个原语记录了用法。信号量通常用于互斥，这会导致优先级反转。等待完成通常是一个同步点，而不是一个互斥点。 */

static void complete_with_flags(struct completion *x, int wake_flags)
{
	unsigned long flags;

	raw_spin_lock_irqsave(&x->wait.lock, flags);

	if (x->done != UINT_MAX)
		x->done++;
   /* swake 链表为空不执行唤醒,有数据尝试唤醒第一个任务,之后删除该任务 */
	swake_up_locked(&x->wait, wake_flags);
	raw_spin_unlock_irqrestore(&x->wait.lock, flags);
}
```

## complete_all 完成量释放所有线程
```c
/** * complete_all: - 信号所有等待这个完成的线程 
 * @x:  持有这个特定完成的状态 * * 这将唤醒所有等待这个特定完成事件的线程。 * 
 * 如果这个函数唤醒了一个任务，它将在访问任务状态之前执行完整的内存屏障。 * 
 * 由于 complete_all() 将 @x 的完成状态永久设为完成，以允许多个等待者结束，如果 @x 需要再次使用，则必须在 @x 上调用 reinit_completion()。 
 代码必须确保在重新初始化 @x 之前，所有的等待者都已经被唤醒并完成。同时需要注意，函数 completion_done() 不能用来判断在调用 complete_all() 后是否还有等待者。 
*/
void complete_all(struct completion *x)
{
	unsigned long flags;

	lockdep_assert_RT_in_threaded_ctx();

	raw_spin_lock_irqsave(&x->wait.lock, flags);
	x->done = UINT_MAX;
	swake_up_all_locked(&x->wait);
	raw_spin_unlock_irqrestore(&x->wait.lock, flags);
}
EXPORT_SYMBOL(complete_all);
```

## complete 完成量释放单个线程
```c
/** * complete: - 表示有一个线程在等待这个完成 
 * @x:  保存这个特定完成的状态 * 
 * 这将唤醒一个在此完成上等待的线程。线程将按照它们被排队的顺序被唤醒。 * 
 * 另见 complete_all()、wait_for_completion() 和相关的例程。 * 
 * 如果此函数唤醒了一个任务，它在访问任务状态之前会执行完整的内存屏障。 */
void complete(struct completion *x)
{
	complete_with_flags(x, 0);
}
EXPORT_SYMBOL(complete);
```

## completion_done 检查完成量是否有等待者
```c
/**
 *	completion_done - 测试完成操作是否有等待者
 *	@x:	完成结构体
 *
 *	返回值: 如果有等待者（正在执行 wait_for_completion()），返回 0；
 *		 如果没有等待者，返回 1。
 *
 *	注意，如果对 @x 调用了 complete_all()，此函数将始终返回 true。
 */
bool completion_done(struct completion *x)
{
	unsigned long flags;

	if (!READ_ONCE(x->done))
		return false;

   /*
   * 如果 ->done，我们需要等待 complete() 释放 ->wait.lock，
   * 否则可能会在 complete() 完成引用之前释放该完成对象。
   */
	raw_spin_lock_irqsave(&x->wait.lock, flags);
	raw_spin_unlock_irqrestore(&x->wait.lock, flags);
	return true;
}
EXPORT_SYMBOL(completion_done);

```

