/**
 * memblock_free_all - release free pages to the buddy allocator
 */
void __init memblock_free_all(void)
{
	unsigned long pages;
	//放未使用的内存映射（memmap）结构。这些结构通常用于描述物理内存页面，但在初始化过程中可能有部分未被使用。通过释放这些未使用的内存，可以减少内存浪费。
