## mm_core_init 设置内核内存分配器
```c
/*
 * 设置内核内存分配器
 */
void __init mm_core_init(void)
{
	arch_mm_preinit();
	hugetlb_bootmem_alloc();

	/*依赖于 SMP 设置的初始化*/
	BUILD_BUG_ON(MAX_ZONELISTS > 2);
