/**
 * idr_remove() - Remove an ID from the IDR.
 * @idr: IDR handle.
 * @id: Pointer ID.
 *
 * 从 IDR 中移除此 ID。如果该 ID 之前不在 IDR 中，则此函数返回 %NULL。 *  
 * 由于此函数修改了 IDR，因此调用者应该提供自己的锁，以确保无法对同一 IDR 进行并发修改。 *  
 * 返回：以前与此 ID 关联的指针。
 */
void *idr_remove(struct idr *idr, unsigned long id)
