## mas_alloc_nodes 将节点分配到 Maple 状态
```c
/*
 * mas_alloc_nodes - 将节点分配到 Maple 状态
 * @mas：枫树状态
 * @gfp：GFP 标志
 */
static inline void mas_alloc_nodes(struct ma_state *mas, gfp_t gfp)
{
	struct maple_alloc *node;
	unsigned long allocated = mas_allocated(mas);
	unsigned int requested = mas_alloc_req(mas);
	unsigned int count;
	void **slots = NULL;
	unsigned int max_req = 0;

	if (!requested)
		return;
	/* 清除当前的分配请求，避免重复分配 */
	mas_set_alloc_req(mas, 0);
	/* 预分配模式检查 */
	if (mas->mas_flags & MA_STATE_PREALLOC) {
		if (allocated)
			return;
		WARN_ON(!allocated);
	}
	/* 如果尚无分配的节点 或当前分配的节点已满 */
	if (!allocated || mas->alloc->node_count == MAPLE_ALLOC_SLOTS) {
		/* 分配一个新节点 */
		node = (struct maple_alloc *)mt_alloc_one(gfp);
		if (!node)
			goto nomem_one;

		if (allocated) {
			node->slot[0] = mas->alloc;
			node->node_count = 1;
		} else {
			node->node_count = 0;
		}

		mas->alloc = node;
		node->total = ++allocated;
		node->request_count = 0;
		requested--;
	}

	node = mas->alloc;
	/* 批量分配节点 */
	while (requested) {
		max_req = MAPLE_ALLOC_SLOTS - node->node_count;
		slots = (void **)&node->slot[node->node_count];
		max_req = min(requested, max_req);
		count = mt_alloc_bulk(gfp, max_req, slots);
		if (!count)
			goto nomem_bulk;

		if (node->node_count == 0) {
			node->slot[0]->node_count = 0;
			node->slot[0]->request_count = 0;
		}

		node->node_count += count;
		allocated += count;
		/* find a non-full node*/
		do {
			node = node->slot[0];
		} while (unlikely(node->node_count == MAPLE_ALLOC_SLOTS));
		requested -= count;
	}
	mas->alloc->total = allocated;
	return;

nomem_bulk:
	/* Clean up potential freed allocations on bulk failure */
	memset(slots, 0, max_req * sizeof(unsigned long));
	mas->alloc->total = allocated;
nomem_one:
	mas_set_alloc_req(mas, requested);
	mas_set_err(mas, -ENOMEM);
}
```

## mas_node_count 计算节点数
```c
/*
 * mas_node_count_gfp（） - 检查是否分配了足够的节点，如果节点数不足，则请求更多节点。
 * @mas：枫树状态
 * @count：所需的节点数
 * @gfp：GFP 标志
 */
static void mas_node_count_gfp(struct ma_state *mas, int count, gfp_t gfp)
{
	unsigned long allocated = mas_allocated(mas);

	if (allocated < count) {
		mas_set_alloc_req(mas, count - allocated);
		mas_alloc_nodes(mas, gfp);
	}
}

/*
 * mas_node_count（） - 检查是否分配了足够的节点，如果节点数不足，则请求更多节点。
 * @mas：枫树状态
 * @count：所需的节点数
 *
 * 注意：使用GFP_NOWAIT |__GFP_NOWARN 用于 gfp 标志。
 */
static void mas_node_count(struct ma_state *mas, int count)
{
	return mas_node_count_gfp(mas, count, GFP_NOWAIT | __GFP_NOWARN);
}
```

## mas_wr_preallocate 为存储作预分配足够的节点
```c
/**
 * mas_wr_preallocate（） - 为存储作预分配足够的节点
 * @wr_mas：maple 写入状态
 * @entry：将要存储的条目
 *
 */
static inline void mas_wr_preallocate(struct ma_wr_state *wr_mas, void *entry)
{
	struct ma_state *mas = wr_mas->mas;
	int request;

	mas_wr_prealloc_setup(wr_mas);
	mas->store_type = mas_wr_store_type(wr_mas);
	/* 计算写操作所需的资源请求量 */
	request = mas_prealloc_calc(mas, entry);
	if (!request)
		return;
	/* 分配所需的节点资源 */
	mas_node_count(mas, request);
}
