## mas_pop_node 从 maple 状态获取先前分配的 maple 节点
```c
/*
 * mas_pop_node（） - 从 maple 状态获取先前分配的 maple 节点。
 * @mas：枫树状态
 *
 * Return：指向 Maple 节点的指针。
 */
static inline struct maple_node *mas_pop_node(struct ma_state *mas)
{
	struct maple_alloc *ret, *node = mas->alloc;
	unsigned long total = mas_allocated(mas);
	unsigned int req = mas_alloc_req(mas);

	/* nothing or a request pending. */
	if (WARN_ON(!total))
		return NULL;

	if (total == 1) {
		/* single allocation in this ma_state */
		mas->alloc = NULL;
		ret = node;
		goto single_node;
	}

	if (node->node_count == 1) {
		/* Single allocation in this node. */
		mas->alloc = node->slot[0];
		mas->alloc->total = node->total - 1;
		ret = node;
		goto new_head;
	}
	node->total--;
	ret = node->slot[--node->node_count];
	node->slot[node->node_count] = NULL;

single_node:
new_head:
	if (req) {
		req++;
		mas_set_alloc_req(mas, req);
	}

	memset(ret, 0, sizeof(*ret));
	return (struct maple_node *)ret;
}
```

## mas_root_expand 将根扩展为节点
```c
/*
 * mas_root_expand（） - 将根扩展为节点
 * @mas：枫树状态
 * @entry：要存储到树中的入口
 */
static inline void mas_root_expand(struct ma_state *mas, void *entry)
{
	/* 获取 mas>tree->ma_root */
	void *contents = mas_root_locked(mas);
	enum maple_type type = maple_leaf_64;
	struct maple_node *node;
	void __rcu **slots;
	unsigned long *pivots;
	int slot = 0;

	node = mas_pop_node(mas);
	pivots = ma_pivots(node, type);
	slots = ma_slots(node, type);
	node->parent = ma_parent_ptr(mas_tree_parent(mas));
	mas->node = mt_mk_node(node, type);
	mas->status = ma_active;

	if (mas->index) {
		if (contents) {
			/* 将其存储到新节点的槽位中 */
			rcu_assign_pointer(slots[slot], contents);
			if (likely(mas->index > 1))
				slot++;
		}
		/* 增加槽位索引 */
		pivots[slot++] = mas->index - 1;
	}
	/* 将新条目（entry）存储到当前槽位 */
	rcu_assign_pointer(slots[slot], entry);
	mas->offset = slot;
	/* 设置枢轴值（pivots），表示条目的范围 */
	pivots[slot] = mas->last;
	/* 如果范围未覆盖 ULONG_MAX，为其添加一个额外的枢轴 */
	if (mas->last != ULONG_MAX)
		pivots[++slot] = ULONG_MAX;
	/* 更新树的元数据 */
	/* 设置树的深度为 1（mas->depth = 1），表示树现在有一个内部节点 */
	mas->depth = 1;
	/*  更新树的高度 */
	mas_set_height(mas);
	/* 设置新节点的元数据 */
	ma_set_meta(node, maple_leaf_64, 0, slot);
	/* 将新根交换到树中*/
	rcu_assign_pointer(mas->tree->ma_root, mte_mk_root(mas->node));
	return;
}
```

## mas_store_root 将值存储到 root 中
```c
/*
 * mas_store_root（） - 将值存储到 root 中。
 * @mas：枫树状态
 * @entry：要存储的入口。
 *
 * 现在没有根节点，我们正在将一个值存储到根节点中 - 这个
 * 函数分配指针或扩展为节点。
 */
static inline void mas_store_root(struct ma_state *mas, void *entry)
{
	if (!entry) {
		if (!mas->index)
			rcu_assign_pointer(mas->tree->ma_root, NULL);
	} else if (likely((mas->last != 0) || (mas->index != 0)))
		mas_root_expand(mas, entry);
	else if (((unsigned long) (entry) & 3) == 2)
		mas_root_expand(mas, entry);
	else {
		rcu_assign_pointer(mas->tree->ma_root, entry);
		mas->status = ma_start;
	}
}
```

## mas_wr_store_entry 用于存储值的内部调用
```c
/*
 * mas_wr_store_entry（） - 用于存储值的内部调用
 * @wr_mas：maple 写入状态
 */
static inline void mas_wr_store_entry(struct ma_wr_state *wr_mas)
{
	struct ma_state *mas = wr_mas->mas;
	unsigned char new_end = mas_wr_new_end(wr_mas);

	switch (mas->store_type) {
	case wr_invalid:
		MT_BUG_ON(mas->tree, 1);
		return;
	case wr_new_root:
		mas_new_root(mas, wr_mas->entry);
		break;
	case wr_store_root:
		mas_store_root(mas, wr_mas->entry);
		break;
	case wr_exact_fit:
		rcu_assign_pointer(wr_mas->slots[mas->offset], wr_mas->entry);
		if (!!wr_mas->entry ^ !!wr_mas->content)
			mas_update_gap(mas);
		break;
	case wr_append:
		mas_wr_append(wr_mas, new_end);
		break;
	case wr_slot_store:
		mas_wr_slot_store(wr_mas);
		break;
	case wr_node_store:
		mas_wr_node_store(wr_mas, new_end);
		break;
	case wr_spanning_store:
		mas_wr_spanning_store(wr_mas);
		break;
	case wr_split_store:
	case wr_rebalance:
		mas_wr_bnode(wr_mas);
		break;
	}

	return;
}
