## rb_erase 从红黑树中删除节点
```c
/*
 * 这是rb_erase()使用的内联版本 - 我们希望能够内联
 * 并消除那里的dummy_rotate回调
 */
static __always_inline void
____rb_erase_color(struct rb_node *parent, struct rb_root *root,
	void (*augment_rotate)(struct rb_node *old, struct rb_node *new))
{
	/* @node: 指向黑高比其他路径少1的那个“问题”节点。初始时为NULL，在循环中可能指向parent。*/
	struct rb_node *node = NULL;
	/* @sibling: 指向node的兄弟节点。*/
	struct rb_node *sibling;
	/* @tmp1, @tmp2: 用于在旋转操作中临时保存节点的指针。*/
	struct rb_node *tmp1, *tmp2;

	/* 这是一个无限循环，通过内部的break或continue来控制流程。*/
	while (true) {
		/*
		 * 循环不变量:
		 * - node是黑色的 (或在第一次迭代时为NULL)
		 * - node不是根节点 (parent不为NULL)
		 * - 所有经过parent和node的叶子路径，其黑色节点计数都比其他叶子路径少1。
		 */

		/* sibling指向parent的右子节点。*/
		sibling = parent->rb_right;
		/*
		 * --- 第一大分支：处理node是parent的左子节点的情况 ---
		 */
		if (node != sibling) {
			/*
			 * 情况1 - 在parent处左旋
			 *
			 *     P               S
			 *    / \             / \
			 *   N   s    -->    p   Sr
			 *      / \         / \
			 *     Sl  Sr      N   Sl
			 */
			/* 如果兄弟节点s是红色的。*/
			if (rb_is_red(sibling)) {
				/* 记录s的左子节点Sl。*/
				tmp1 = sibling->rb_left;
				/* p的右指针指向Sl。*/
				WRITE_ONCE(parent->rb_right, tmp1);
				/* s的左指针指向p。*/
				WRITE_ONCE(sibling->rb_left, parent);
				/* Sl变为黑色，其父节点变为p。*/
				rb_set_parent_color(tmp1, parent, RB_BLACK);
				/* 执行旋转，s成为新的父节点，p变为红色。*/
				__rb_rotate_set_parents(parent, sibling, root, RB_RED);
				/* 调用回调，更新旋转后节点的增强数据。*/
				augment_rotate(parent, sibling);
				/* 更新sibling，现在node的新兄弟是Sl。*/
				sibling = tmp1;
			}
			/* 获取新sibling的右子节点Sr。*/
			tmp1 = sibling->rb_right;
			/* 如果Sr不存在或者是黑色的。*/
			if (!tmp1 || rb_is_black(tmp1)) {
				/* 获取新sibling的左子节点Sl。*/
				tmp2 = sibling->rb_left;
				/* 如果Sl也不存在或者是黑色的。*/
				if (!tmp2 || rb_is_black(tmp2)) {
					/*
					 * 情况2 - 兄弟节点颜色翻转
					 * (此时p可以是任何颜色)
					 *
					 *    (p)           (p)
					 *    / \           / \
					 *   N   S    -->  N   s
					 *      / \           / \
					 *     Sl  Sr        Sl  Sr
					 *
					 * 这会使我们违反性质5，可以通过将p翻转为黑色（如果它曾是红色），
					 * 或者在p处递归来修复。当从情况1过来时，p是红色的。
					 */
					/* 将兄弟节点S变为红色。*/
					rb_set_parent_color(sibling, parent, RB_RED);
					/* 如果父节点p是红色的。*/
					if (rb_is_red(parent))
						/* 将p变为黑色，黑高平衡，修复完成，退出循环。*/
						rb_set_black(parent);
					else {
						/* 如果p是黑色的，则问题被上移到p。*/
						node = parent;
						parent = rb_parent(node);
						/* 如果p不是根节点，则继续下一轮循环。*/
						if (parent)
							continue;
					}
					/* 修复完成或已达根节点，退出循环。*/
					break;
				}
				/*
				 * 情况3 - 在sibling处右旋
				 * (此时p可以是任何颜色)
				 *
				 *   (p)           (p)
				 *   / \           / \
				 *  N   S    -->  N   sl
				 *     / \             \
				 *    sl  Sr            S
				 *                       \
				 *                        Sr
				 */
				/* ... (省略了与情况1、4类似的指针操作和颜色翻转) ... */
				tmp1 = tmp2->rb_right;
				WRITE_ONCE(sibling->rb_left, tmp1);
				WRITE_ONCE(tmp2->rb_right, sibling);
				WRITE_ONCE(parent->rb_right, tmp2);
				if (tmp1)
					rb_set_parent_color(tmp1, sibling, RB_BLACK);
				augment_rotate(sibling, tmp2);
				tmp1 = sibling;
				sibling = tmp2;
			}
			/*
			 * 情况4 - 在parent处左旋 + 颜色翻转
			 *
			 *      (p)             (s)
			 *      / \             / \
			 *     N   S     -->   P   Sr
			 *        / \         / \
			 *      (sl) sr      N  (sl)
			 */
			/* ... (省略了与情况1类似的指针操作和颜色翻转) ... */
			tmp2 = sibling->rb_left;
			WRITE_ONCE(parent->rb_right, tmp2);
			WRITE_ONCE(sibling->rb_left, parent);
			rb_set_parent_color(tmp1, sibling, RB_BLACK);
			if (tmp2)
				rb_set_parent(tmp2, parent);
			__rb_rotate_set_parents(parent, sibling, root, RB_BLACK);
			augment_rotate(parent, sibling);
			/* 这是终止情况，修复完成，退出循环。*/
			break;
		} else {
		/*
		 * --- 第二大分支：处理node是parent的右子节点的情况 ---
		 * 这部分代码与第一大分支完全对称，只是旋转方向和左右子节点的处理相反。
		 */
			sibling = parent->rb_left;
			if (rb_is_red(sibling)) {
				/* 对称的情况1 - 在parent处右旋 */
				tmp1 = sibling->rb_right;
				WRITE_ONCE(parent->rb_left, tmp1);
				WRITE_ONCE(sibling->rb_right, parent);
				rb_set_parent_color(tmp1, parent, RB_BLACK);
				__rb_rotate_set_parents(parent, sibling, root, RB_RED);
				augment_rotate(parent, sibling);
				sibling = tmp1;
			}
			tmp1 = sibling->rb_left;
			if (!tmp1 || rb_is_black(tmp1)) {
				tmp2 = sibling->rb_right;
				if (!tmp2 || rb_is_black(tmp2)) {
					/* 对称的情况2 - 兄弟节点颜色翻转 */
					rb_set_parent_color(sibling, parent, RB_RED);
					if (rb_is_red(parent))
						rb_set_black(parent);
					else {
						node = parent;
						parent = rb_parent(node);
						if (parent)
							continue;
					}
					break;
				}
				/* 对称的情况3 - 在sibling处左旋 */
				tmp1 = tmp2->rb_left;
				WRITE_ONCE(sibling->rb_right, tmp1);
				WRITE_ONCE(tmp2->rb_left, sibling);
				WRITE_ONCE(parent->rb_left, tmp2);
				if (tmp1)
					rb_set_parent_color(tmp1, sibling, RB_BLACK);
				augment_rotate(sibling, tmp2);
				tmp1 = sibling;
				sibling = tmp2;
			}
			/* 对称的情况4 - 在parent处右旋 + 颜色翻转 */
			tmp2 = sibling->rb_right;
			WRITE_ONCE(parent->rb_left, tmp2);
			WRITE_ONCE(sibling->rb_right, parent);
			rb_set_parent_color(tmp1, sibling, RB_BLACK);
			if (tmp2)
				rb_set_parent(tmp2, parent);
			__rb_rotate_set_parents(parent, sibling, root, RB_BLACK);
			augment_rotate(parent, sibling);
			/* 这是终止情况，修复完成，退出循环。*/
			break;
		}
	}
}

/*
 * 非内联版本，供rb_erase_augmented()使用。
 * 它被导出(EXPORT_SYMBOL)，以便内核模块也能调用。
 */
void __rb_erase_color(struct rb_node *parent, struct rb_root *root,
	void (*augment_rotate)(struct rb_node *old, struct rb_node *new))
{
	/* 直接调用内联的、实现核心逻辑的函数。*/
	____rb_erase_color(parent, root, augment_rotate);
}
/* 将__rb_erase_color符号导出到内核符号表。*/
EXPORT_SYMBOL(__rb_erase_color);
