# lib/string.c
## sized_strscpy - 将 C 字符串复制到指定大小的缓冲区中
```c
ssize_t sized_strscpy(char *dest, const char *src, size_t count)
{
	const struct word_at_a_time constants = WORD_AT_A_TIME_CONSTANTS;
	size_t max = count;
	long res = 0;

	if (count == 0 || WARN_ON_ONCE(count > INT_MAX))
		return -E2BIG;

#ifndef CONFIG_DCACHE_WORD_ACCESS
#ifdef CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS
	/*
	 * If src is unaligned, don't cross a page boundary,
	 * since we don't know if the next page is mapped.
	 */
	if ((long)src & (sizeof(long) - 1)) {
		size_t limit = PAGE_SIZE - ((long)src & (PAGE_SIZE - 1));
		if (limit < max)
			max = limit;
	}
#else
	/* 如果源或目标未对齐，则不要一次处理一个字。 */
	if (((long) dest | (long) src) & (sizeof(long) - 1))
		max = 0;
#endif
#endif

	/*
	 * load_unaligned_zeropad() or read_word_at_a_time() below may read
	 * uninitialized bytes after the trailing zero and use them in
	 * comparisons. Disable this optimization under KMSAN to prevent
	 * false positive reports.
	 */
	if (IS_ENABLED(CONFIG_KMSAN))
		max = 0;

	while (max >= sizeof(unsigned long)) {
		unsigned long c, data;

#ifdef CONFIG_DCACHE_WORD_ACCESS
		c = load_unaligned_zeropad(src+res);
#else
		c = read_word_at_a_time(src+res);
#endif
        /* 检查数据块是否包含空字符 */
		if (has_zero(c, &data, &constants)) {
            /* 标记空字符的位置 */
			data = prep_zero_mask(c, data, &constants);
            /* 生成最终的字节掩码 */
			data = create_zero_mask(data);
            /* 提取数据块 c 中的有效字节（即非空字符）。
            将处理后的数据块写入目标缓冲区 dest 的偏移位置 res */
			*(unsigned long *)(dest+res) = c & zero_bytemask(data);
			return res + find_zero(data);
		}
		count -= sizeof(unsigned long);
        /* 如果 count 为零，表示目标缓冲区已满，无法继续复制 */
		if (unlikely(!count)) {
            /* ALLBUTLAST_BYTE_MASK 是一个掩码，用于清除数据块 c 中的最后一个字节 */
			c &= ALLBUTLAST_BYTE_MASK;
			*(unsigned long *)(dest+res) = c;
			return -E2BIG;
		}
		*(unsigned long *)(dest+res) = c;
		res += sizeof(unsigned long);
		max -= sizeof(unsigned long);
	}

    /* 逐字节地将源字符串 src 的内容复制到目标缓冲区 dest。
    * 它通过循环逐个字符地处理字符串，
    * 同时检查是否遇到字符串的终止符 %NUL（空字符），
    * 以确保目标缓冲区正确终止 */
	while (count > 1) {
		char c;

		c = src[res];
		dest[res] = c;
		if (!c)
			return res;
		res++;
		count--;
	}

	/* Force NUL-termination. */
	dest[res] = '\0';

	/* Return E2BIG if the source didn't stop */
	return src[res] ? -E2BIG : res;
}
EXPORT_SYMBOL(sized_strscpy);
```

